insert into public.chunks (id, episode_id, cms_item_id, chunk_index, content, token_estimate, speakers, start_timestamp, end_timestamp, podcast_index, episode_name, slug, web_url, guest_name, guest_title, categories, short_description, podcast_length)
select id, episode_id, cms_item_id, chunk_index, content, token_estimate, speakers, start_timestamp, end_timestamp, podcast_index, episode_name, slug, web_url, guest_name, guest_title, categories, short_description, podcast_length
from jsonb_to_recordset($jsonpayload$
[{"id": "ee5a563e-4773-4a60-aa58-428a82b775eb", "episode_id": "d058428f-f662-4d1f-aa49-5ff24f16cac3", "cms_item_id": "68225dfc7bb476527f8c4862", "chunk_index": 2, "content": "Cole Heilborn (06:04): Man. Talk about a fun transition from the industrial design to the marketing, but it sounds like that was a pretty natural transition for you.\n\nDavid Zimberoff (06:15): It was super awkward at first, right? Because I think the challenge is society tells you whatever you do in school, whatever you learn, whatever your degree is, that's what you do for life. This is my degree, and so this is what I do. And so I was really torn while I wanted to do marketing. I actually wanted to do both, and my first ask to the organization was, Hey, can I be in charge of industrial design and marketing? I couldn't let go of that. My degree, I have a bachelor of Science in Industrial Design and have it framed diploma on the wall, and I'm so proud and spent a lot of money on it, and that's what I should do. I originally went to the team and said, Hey, can I do both? And they looked at me and said, no, but we've got an alternative for you. (07:13): Why don't you just take over marketing, give up industrial design? So I was torn, but I spoke with a bunch of my mentors and colleagues and they're like, Dave, you got to do this. Everything's a stepping stone to something bigger and something better. Don't think about it as you giving up industrial design. Think about it as you growing and learning more. And so I think one of the advantages for me personally is that knowing how product is made, even if it's just an industrial design capacity, the aesthetics and ergonomics and human factors, I still had very close ties to engineering and product development. Knowing how product is made in a marketing role is hugely valuable because I can sort of sniff out the bullshit meter, so to speak, if product development saying, no, no, no, you don't understand. It's got this whizzbang technology, blah, blah. And I'm like, I don't think so. I think our consumer's going to see that. And so I'm able to see that, and so I think it makes me more valuable having done both and the transition while awkward at first I think has really turned into something super valuable.", "token_estimate": 522, "speakers": ["Cole Heilborn", "David Zimberoff"], "start_timestamp": "06:04", "end_timestamp": "06:15", "podcast_index": 61, "episode_name": "EP 61: David Zimberoff | Leadership & Spending Brand Culture | SRAM", "slug": "ep-61-david-zimberoff-leadership-spending-brand-culture-sram-bb20e", "web_url": "https://www.portsidepro.com/podcast-feed/ep-61-david-zimberoff-leadership-spending-brand-culture-sram-bb20e", "guest_name": "David Zimberoff", "guest_title": "VP of Marketing, SRAM", "categories": [], "short_description": "The challenges of leading a marketing team while working remotely", "podcast_length": "44:83"}, {"id": "4344c6f3-1616-4993-a674-803a16643dd5", "episode_id": "d058428f-f662-4d1f-aa49-5ff24f16cac3", "cms_item_id": "68225dfc7bb476527f8c4862", "chunk_index": 3, "content": "Cole Heilborn (08:28): And over that time, obviously the marketing team has grown from you to the 60 plus people that you guys now work with. How has that been from going from the person who's doing everything to the person now who's helping lead a bunch of people?\n\nDavid Zimberoff (08:44): Yeah, super hard. Great question and something that oftentimes individual contributors face in their lives. You go from being the doer to the manager. That's been really hard and it's not really for everybody. You either have the DNA to be a manager or you can learn or you don't. And for me, while it was hard to give up what I've done in my private life is taking that sort of creativity, that individual creativity and just replaced it with other things in my life personally that I don't necessarily get at work. Because at work, it's all about the team. It's all about building the team and letting go and delegating and making them the best that they can be. But if inherently I myself am a creative and I need to create and design, I had to let that go. And so I just turned that inward at home and I'm creative with my family and I'm creative just on my own doing, building, designing, making. So I fulfill that need privately and I make sure that my team has that need at work.\n\nCole Heilborn (10:06): Yeah. Talk about a team. I feel like, again, folks that are familiar with ra, I picture you guys at Crank Works up at Whistler with the giant RA tent and the party that starts and ends there. Before COVID, what was Thera work culture? I feel like as an outsider looking in, it's got to be a pretty cool place to be.", "token_estimate": 405, "speakers": ["Cole Heilborn", "David Zimberoff"], "start_timestamp": "08:28", "end_timestamp": "10:06", "podcast_index": 61, "episode_name": "EP 61: David Zimberoff | Leadership & Spending Brand Culture | SRAM", "slug": "ep-61-david-zimberoff-leadership-spending-brand-culture-sram-bb20e", "web_url": "https://www.portsidepro.com/podcast-feed/ep-61-david-zimberoff-leadership-spending-brand-culture-sram-bb20e", "guest_name": "David Zimberoff", "guest_title": "VP of Marketing, SRAM", "categories": [], "short_description": "The challenges of leading a marketing team while working remotely", "podcast_length": "44:83"}, {"id": "2434e49f-3e10-4045-a674-4749bec5c72a", "episode_id": "d058428f-f662-4d1f-aa49-5ff24f16cac3", "cms_item_id": "68225dfc7bb476527f8c4862", "chunk_index": 4, "content": "David Zimberoff (10:34): Yeah, it is. The pre COVID SRAM work culture, there are a lot of similarities. We're a global team. We have offices and people in a dozen locations around the world, so we are already global. We are already in lots of different countries and time zones, so that's a big piece of it. Global team is a big piece of who we are. Global cultures. We have almost every culture sitting on our team, which is really exciting, so different perspectives, but a lot of what our pre COVID culture was live working in offices, going to events, whether it be a Sea Otter or Crank Works or Tour France or a Eurobike. We were live in the marketing and product development group. A lot of what we do to promote our products are what we call product launches or media launches. And so a lot of our culture was very experiential where we would create an event or an activity and we would invite guests, whether it be customers, retailers or journalists to a location. And for a week or two, we would sort of walk people through what makes our product tick and then ride. So riding was a big piece of our culture, so seeing people working live in rooms and experience was a big piece, which I desperately miss. That's been hard.\n\nCole Heilborn (12:09): I can only imagine. And especially now that I'm assuming things have changed quite considerably for you and those types of events and in-person interactions don't happen. How has that transition gone, I guess? What does the work culture look like now in the day to day?", "token_estimate": 382, "speakers": ["David Zimberoff", "Cole Heilborn"], "start_timestamp": "10:34", "end_timestamp": "12:09", "podcast_index": 61, "episode_name": "EP 61: David Zimberoff | Leadership & Spending Brand Culture | SRAM", "slug": "ep-61-david-zimberoff-leadership-spending-brand-culture-sram-bb20e", "web_url": "https://www.portsidepro.com/podcast-feed/ep-61-david-zimberoff-leadership-spending-brand-culture-sram-bb20e", "guest_name": "David Zimberoff", "guest_title": "VP of Marketing, SRAM", "categories": [], "short_description": "The challenges of leading a marketing team while working remotely", "podcast_length": "44:83"}, {"id": "82104592-38c9-4312-a3b4-57c4c6186651", "episode_id": "d058428f-f662-4d1f-aa49-5ff24f16cac3", "cms_item_id": "68225dfc7bb476527f8c4862", "chunk_index": 5, "content": "David Zimberoff (12:27): Yeah. No, it's been a really weird transition March of 2020, right? Almost coming up on a year now. When the first lockdown happened, we transitioned almost overnight to a work from home culture, and that was really hard and we prepared ourselves for the worst in that first quarter, march, April, may, if you all remember was rough. The good thing is, and I shared this term with you in our brief, we talk about this concept of corporate culture and either building your corporate culture or spending your corporate culture for 25 or 30 years, RA has built this corporate culture of being with each other, being live, riding together, lunch rides, working in conference rooms, whiteboards, traveling, waiting in airports, et cetera, all the good and the bad. We built this culture fortunately for ra. Most of our team members have been with us for a very, very long time, and so we've built a corporate culture bank account that we've been building for decades. (13:43): Well, overnight we go working from home and this concept of are we building our corporate culture, are we spending against our corporate culture? We had to ask ourselves that question and what can we do to maintain that corporate culture in a work from home environment? Fortunately, again, as I said, we know each other, we've worked with each other and we're able to ride the whitewater, so to speak for a little while, but we've had to look inwards and figure out how to keep glued together and certainly technology has been a huge piece of that. We're able to use Zoom and teams and GoToMeeting and video conferencing to supplement some of that. We've gone to virtual whiteboards for collaboration, and really what we're doing is we're sort of withdrawing from our corporate culture a little bit, but fortunately our bank account's really, really, really big. So we're able to do that. But we've had virtual happy hours, virtual gifting. We've done a really good job at converting to work from home, and fortunately we're slowly starting to come back into the office in small percentages depending on location. In some offices, we're up to 25%. Some offices we're up to 50%, and in the next four months we'll get up quick and then we'll be super flexible depending on people's different situations. But it's definitely been hard, I think. But we've done a great job because I think our corporate culture is so strong.", "token_estimate": 605, "speakers": ["David Zimberoff"], "start_timestamp": "12:27", "end_timestamp": "12:27", "podcast_index": 61, "episode_name": "EP 61: David Zimberoff | Leadership & Spending Brand Culture | SRAM", "slug": "ep-61-david-zimberoff-leadership-spending-brand-culture-sram-bb20e", "web_url": "https://www.portsidepro.com/podcast-feed/ep-61-david-zimberoff-leadership-spending-brand-culture-sram-bb20e", "guest_name": "David Zimberoff", "guest_title": "VP of Marketing, SRAM", "categories": [], "short_description": "The challenges of leading a marketing team while working remotely", "podcast_length": "44:83"}, {"id": "89d211b7-53c5-42a6-81bb-b31d9137c923", "episode_id": "d058428f-f662-4d1f-aa49-5ff24f16cac3", "cms_item_id": "68225dfc7bb476527f8c4862", "chunk_index": 6, "content": "Cole Heilborn (15:28): So do you see every day that the team isn't in person collaborating together as spending corporate culture, as you say?\n\nDavid Zimberoff (15:38): I think so, yeah. Even if just a little bit every day we're working from home, we're absolutely taken withdrawals from that corporate culture bank account. You can only do so much on teams and GoToMeeting and Zoom because inherently humans are human and they want to be together with people. Even though this is a killer format that you've locked in on for or for this type of activity, gosh, wouldn't it be great if we could have a beer together?\n\nCole Heilborn (16:12): But also that brings up so many other challenges, mostly just the difference in location. I mean, honestly speaking truthfully, the only reason this podcast has worked is because I think people are used to Zoom interactions right now. If we tried to launch this three years ago when no one wanted to spend time on a video conferencing platform, I'm not sure that it would've worked. So yes, I would definitely prefer a beer, but I think this is one of those things that's come out of the new normal.", "token_estimate": 285, "speakers": ["Cole Heilborn", "David Zimberoff"], "start_timestamp": "15:28", "end_timestamp": "16:12", "podcast_index": 61, "episode_name": "EP 61: David Zimberoff | Leadership & Spending Brand Culture | SRAM", "slug": "ep-61-david-zimberoff-leadership-spending-brand-culture-sram-bb20e", "web_url": "https://www.portsidepro.com/podcast-feed/ep-61-david-zimberoff-leadership-spending-brand-culture-sram-bb20e", "guest_name": "David Zimberoff", "guest_title": "VP of Marketing, SRAM", "categories": [], "short_description": "The challenges of leading a marketing team while working remotely", "podcast_length": "44:83"}, {"id": "65ff0f55-719c-4b0e-b2b9-709b8f4d9ba4", "episode_id": "d058428f-f662-4d1f-aa49-5ff24f16cac3", "cms_item_id": "68225dfc7bb476527f8c4862", "chunk_index": 7, "content": "David Zimberoff (16:41): Yeah, your business model for sure is going to take full advantage of this, but I'll give you a case study for us. So these media launches that we would have, where we would get together when you arrive with journalists, how do we do that? We can't do that over video, not with a group. So we're having to use technology. We've actually sent customers product, future product in a box, and inside the box is an iPad, and that iPad has a video or it's a link to us back at hq, and it's sort of like some future movie, like a mission impossible scene. You open the video, you play it, and this will self-destruct in 30 seconds and then the customer or the journalist goes out for a ride and it's very one-on-one. But relationship building is really also part of our success, and I think part of what we're missing in this environment, Cole, you and I have never met live, we've never shook hands, we've never had that beer, and so we're never going to go on a bike ride until we see each other. So how far is our relationship really going to go? It's going to be very virtual, and so relationships are hugely important in business. So back to that, are you building your bank account or your corporate culture? You're spending it from a relationship perspective. This is good. It's not great.\n\nCole Heilborn (18:16): So how do you combat that? At what point does the virtual connection, I guess, what do you lose from it? Is there a way to quantify that?", "token_estimate": 370, "speakers": ["David Zimberoff", "Cole Heilborn"], "start_timestamp": "16:41", "end_timestamp": "18:16", "podcast_index": 61, "episode_name": "EP 61: David Zimberoff | Leadership & Spending Brand Culture | SRAM", "slug": "ep-61-david-zimberoff-leadership-spending-brand-culture-sram-bb20e", "web_url": "https://www.portsidepro.com/podcast-feed/ep-61-david-zimberoff-leadership-spending-brand-culture-sram-bb20e", "guest_name": "David Zimberoff", "guest_title": "VP of Marketing, SRAM", "categories": [], "short_description": "The challenges of leading a marketing team while working remotely", "podcast_length": "44:83"}, {"id": "3dfabd89-60b3-4fff-af7d-de0d0e562f35", "episode_id": "d058428f-f662-4d1f-aa49-5ff24f16cac3", "cms_item_id": "68225dfc7bb476527f8c4862", "chunk_index": 8, "content": "David Zimberoff (18:28): There probably is. I wish I had an easy answer and I don't want to mansplain an answer, but I'll just give you my point of view, my perspective, I think it's about how strong is your corporate culture and how much time are you going to be in that environment? We can ride this out probably a couple years because I think we're really strong and we're going to overcompensate in some areas. We're going to have surprise and delight schwag packages that we mail to people. We're going to send people gifts. We are going to do virtual happy hours, we're going to increase our investment in online education and everything that we can do to take advantage of this technology and this time, but it's only a matter of time that that bank account withdrawal starts to take a significant chunk out. But I feel really good about RA's corporate culture and the people because we're tight. (19:35): The big challenge though is with some of our new team members that we've just onboarded who we've onboarded into a virtual environment or we've onboarded into an environment that has very few people in the office, they're really missing out. We often joke atra, when you start atra, usually within the first month you got to have your passport ready and you're hopping on a plane and you're visiting some location somewhere, whether it be a factory or an event, but it's get in, get on, buckle up, hold on, tight drink from a fire hose. And so in this environment, that's really tough. So it's the new team members that I'm most concerned about.\n\nCole Heilborn (20:20): So as the leader, one of the leaders, how do you help the team? How do you help the veteran who's been there for 10 years who maybe has a little more culture in the bank account they can lean on, but for that new team member, how do you help them get up to speed?", "token_estimate": 462, "speakers": ["David Zimberoff", "Cole Heilborn"], "start_timestamp": "18:28", "end_timestamp": "20:20", "podcast_index": 61, "episode_name": "EP 61: David Zimberoff | Leadership & Spending Brand Culture | SRAM", "slug": "ep-61-david-zimberoff-leadership-spending-brand-culture-sram-bb20e", "web_url": "https://www.portsidepro.com/podcast-feed/ep-61-david-zimberoff-leadership-spending-brand-culture-sram-bb20e", "guest_name": "David Zimberoff", "guest_title": "VP of Marketing, SRAM", "categories": [], "short_description": "The challenges of leading a marketing team while working remotely", "podcast_length": "44:83"}, {"id": "949b4bf8-0465-428c-88d8-6d708229a095", "episode_id": "d058428f-f662-4d1f-aa49-5ff24f16cac3", "cms_item_id": "68225dfc7bb476527f8c4862", "chunk_index": 9, "content": "David Zimberoff (20:45): I think it's really about maintaining what we have. It's about sharing as much as we have as we can. It's about being as open and transparent as possible. We're pretty open and transparent culture as it is. If I will just take one case study, we just recently onboarded a new race technician in Chicago and she's super awesome. She came from a bike shop and she came on board to provide service and support to the North American road racing scene, the athletes and ambassadors and race teams that we have Racing Road in the United States, well, that season's kind of almost dead, but we had someone who left that position, so we needed to replace that because there's still a lot of activity. So she started in a virtual environment and she comes to an office with very, very low live participation. So what we do is I personally try to make it to the office once a week to make sure that she sees people. (21:59): Her direct manager is actually in Europe. We increase our one-on-ones using technology, and we just make ourselves available and basically educate and share and be as flexible as possible. We also have to respect that there's certain personal situations, whether it be COVID related or not. Geography, we're super accommodating and flexible and transparent and sharing. That's kind of the only thing we can do to keep that going. But at some point we're going to run out. We're going to run, we can only send so many t-shirts and so many six packs of beer home for our team members. At some point we got to get busy and get back in the office.\n\nCole Heilborn (22:52): Do you see that is being the only way to start adding to the bank account is to get back in person? Is that what you see as the thing that the light at the end of the tunnel?", "token_estimate": 446, "speakers": ["David Zimberoff", "Cole Heilborn"], "start_timestamp": "20:45", "end_timestamp": "22:52", "podcast_index": 61, "episode_name": "EP 61: David Zimberoff | Leadership & Spending Brand Culture | SRAM", "slug": "ep-61-david-zimberoff-leadership-spending-brand-culture-sram-bb20e", "web_url": "https://www.portsidepro.com/podcast-feed/ep-61-david-zimberoff-leadership-spending-brand-culture-sram-bb20e", "guest_name": "David Zimberoff", "guest_title": "VP of Marketing, SRAM", "categories": [], "short_description": "The challenges of leading a marketing team while working remotely", "podcast_length": "44:83"}, {"id": "926a6ca9-c64d-4a40-a6dd-676c851a639a", "episode_id": "d058428f-f662-4d1f-aa49-5ff24f16cac3", "cms_item_id": "68225dfc7bb476527f8c4862", "chunk_index": 10, "content": "David Zimberoff (23:06): I don't think it's the only thing, and I think about when everybody has their vaccine and herd immunity is achieved or whatever metric the country is following, it's not going to be a magic switch and we're not going to revert to old normal. There'll be a new normal, and so our bank account will have dwindled a little bit. Our corporate culture bank account will have dwindled a little bit, and as soon as we get to whatever the new normal is, whether it's a hybrid, we'll start building it back up in a new normal and that new normal is going include some of these things. We're going to travel less. There will be fewer events. We will do more virtual activities, and so we will absolutely start building it fast when the vaccine is widely distributed, but it's going to be a slightly different new corporate culture.\n\nCole Heilborn (24:11): What type of impact have you seen from the team, whether that's work performance, quality of work, mental health, just general excitement about being on the team and the work you're doing?", "token_estimate": 265, "speakers": ["David Zimberoff", "Cole Heilborn"], "start_timestamp": "23:06", "end_timestamp": "24:11", "podcast_index": 61, "episode_name": "EP 61: David Zimberoff | Leadership & Spending Brand Culture | SRAM", "slug": "ep-61-david-zimberoff-leadership-spending-brand-culture-sram-bb20e", "web_url": "https://www.portsidepro.com/podcast-feed/ep-61-david-zimberoff-leadership-spending-brand-culture-sram-bb20e", "guest_name": "David Zimberoff", "guest_title": "VP of Marketing, SRAM", "categories": [], "short_description": "The challenges of leading a marketing team while working remotely", "podcast_length": "44:83"}, {"id": "1be177e1-5438-4c99-a24e-7f7c30775da4", "episode_id": "d058428f-f662-4d1f-aa49-5ff24f16cac3", "cms_item_id": "68225dfc7bb476527f8c4862", "chunk_index": 11, "content": "David Zimberoff (24:24): The team has had a variety of different types of impacts. On one hand, everyone has really stepped up and we are having more meetings and we are more engaged and I think we ever were. And part of that is because of technology. We are all on camera on all the time. I think part of us tends to work a bit more also than we ever have. We're commuting less, so we're probably filling that time from a mental health. It's absolutely something that the senior management team at RA is hyper-focused on, and we have a lot of check-ins with our team members, making sure they are comfortable, healthy, happy, sane, need anything, et cetera. Because it is hard as, especially if you're not used to working from home, that void, that interpersonal void is big. And so the senior management group talks about it a lot. (25:30): And one fun new one that we've started to do or that we've done a lot more of during this COVID time has been celebrating team members years of service. And that seemed to really stoke the whole team. So what we do is every team member that passes a 5, 10, 15, 20 milestone, we host basically it's kind of like a roast or an award ceremony. And so the manager of that team member puts together a short three to five minute slideshow and story about the team member what used to happen once a year in one location. Now we're doing them it seems like almost monthly and the whole office. And because of this technology, we're not limited to geography. Anyone can join and listen in. So we've basically expanded the celebration of our people and these years of service awards are hysterical because they're half acknowledging the great contribution the team member has provided. But then depending on the team member, they're kind of half hysterically funny and like, geez, if you didn't know this person, here's their deep secrets. It's pretty great.\n\nCole Heilborn (26:57): Yeah. Do you feel like that's one of the positives that could come out of this is more connection amongst a global team like yourself being able to be in the office and using these types of digital tools?", "token_estimate": 530, "speakers": ["David Zimberoff", "Cole Heilborn"], "start_timestamp": "24:24", "end_timestamp": "26:57", "podcast_index": 61, "episode_name": "EP 61: David Zimberoff | Leadership & Spending Brand Culture | SRAM", "slug": "ep-61-david-zimberoff-leadership-spending-brand-culture-sram-bb20e", "web_url": "https://www.portsidepro.com/podcast-feed/ep-61-david-zimberoff-leadership-spending-brand-culture-sram-bb20e", "guest_name": "David Zimberoff", "guest_title": "VP of Marketing, SRAM", "categories": [], "short_description": "The challenges of leading a marketing team while working remotely", "podcast_length": "44:83"}, {"id": "6ec01803-0937-4c28-bfb0-0e24c22cbd63", "episode_id": "d058428f-f662-4d1f-aa49-5ff24f16cac3", "cms_item_id": "68225dfc7bb476527f8c4862", "chunk_index": 12, "content": "David Zimberoff (27:12): Yeah, absolutely. Yeah, technology has definitely improved that piece. It's never going to replace it though, right? A virtual beer versus a real beer. I keep saying beer, but insert any beverage you want there, but it's been great. Yeah, I mean, I have had more face-to-face live video interaction with more people than ever before, and I'm super thankful of it. So the marketing team is about 60. Of those 60, my direct reports are about nine and prior pre COVID, I would have weekly one-on-ones with everyone on my team, common management technique, the one-on-one and pre COVID, well, actually out of those nine team members, only one is with me in Chicago. So eight are in other locations. So the one in Chicago, we would meet live, the eight not in Chicago. We would meet on the phone but not on video. And so I think here's a perfect example that has really, I think created a tighter bond with those eight. And now we actually talk about it. We're like, okay, post COVID, are we going to still do these video? Absolutely. We're going to do these video one-on-ones because they're just so much better than a phone call. Little things like that are great, these surprise and delight swag deliveries. I think that'll continue with not only our team members but customers to stoke people out. (29:00): Is it better to go to a crank works and hand out a hat physically or do we just mail 'em? Do we just mail 'em to our top customers? So I think we'll do both eventually, but that we'll definitely take advantage of shipping things too.\n\nCole Heilborn (29:18): I got to say, it's pretty fun when someone's on the chairlift, Chuck Andra hats from it, and you're trying to catch 'em below. You can't beat that.", "token_estimate": 434, "speakers": ["David Zimberoff", "Cole Heilborn"], "start_timestamp": "27:12", "end_timestamp": "29:18", "podcast_index": 61, "episode_name": "EP 61: David Zimberoff | Leadership & Spending Brand Culture | SRAM", "slug": "ep-61-david-zimberoff-leadership-spending-brand-culture-sram-bb20e", "web_url": "https://www.portsidepro.com/podcast-feed/ep-61-david-zimberoff-leadership-spending-brand-culture-sram-bb20e", "guest_name": "David Zimberoff", "guest_title": "VP of Marketing, SRAM", "categories": [], "short_description": "The challenges of leading a marketing team while working remotely", "podcast_length": "44:83"}, {"id": "3464c32c-f444-48b0-9716-672ad50f0300", "episode_id": "d058428f-f662-4d1f-aa49-5ff24f16cac3", "cms_item_id": "68225dfc7bb476527f8c4862", "chunk_index": 13, "content": "David Zimberoff (29:28): And we'll still do that, and we are super eager for that side of the business to open up. That's probably going to be a bit slower than we'd like. I mean, I've just heard that UCI is pushing out the first couple World Cup events, so that's a bit of a bummer. And some events that are going to happen are going to happen without spectators. So we're probably still another year away from getting back to what you and I remember as a Crank Works type event. But it'll happen 2020, I'd say 2022 maybe.\n\nCole Heilborn (30:07): We'll see. How has the creative team been impacted? And I say creative loosely. I know a lot of people have been concerned just about creative performance, so much of creativity as being in the same room, bouncing ideas off each other. Have you lost any of that?", "token_estimate": 203, "speakers": ["David Zimberoff", "Cole Heilborn"], "start_timestamp": "29:28", "end_timestamp": "30:07", "podcast_index": 61, "episode_name": "EP 61: David Zimberoff | Leadership & Spending Brand Culture | SRAM", "slug": "ep-61-david-zimberoff-leadership-spending-brand-culture-sram-bb20e", "web_url": "https://www.portsidepro.com/podcast-feed/ep-61-david-zimberoff-leadership-spending-brand-culture-sram-bb20e", "guest_name": "David Zimberoff", "guest_title": "VP of Marketing, SRAM", "categories": [], "short_description": "The challenges of leading a marketing team while working remotely", "podcast_length": "44:83"}, {"id": "2ec6356a-fda3-4b6f-b305-39ac3e381e17", "episode_id": "d058428f-f662-4d1f-aa49-5ff24f16cac3", "cms_item_id": "68225dfc7bb476527f8c4862", "chunk_index": 14, "content": "David Zimberoff (30:31): That's a good question. So in the marketing group, we have a creative director and he has about a team of 10 plus or minus. Some of those are three dimensional designers that are doing 3D renderings and imaging. Those are pretty block and tackle kind of creative outputs. They aren't impacted, I'd say the graphic designers and design managers are a bit more impacted. It hasn't been a huge hit to the team. They've been able to stay productive our offices, while we recommend that most people work from home if they can, our offices are still open to those that need to or want to. Our creative team has taken, and most of them are in Chicago, our creative team has with the right precautions when they've needed to. They've gone in the office and done the brainstorms just with all the proper social distancing and hygiene recommendations. (31:33): They've done a bunch of brainstorm sessions, so I don't think we've skipped a beat other than just missing each other and missing some of that human interaction. But they've stayed pretty killer. And if anyone's seen the recent announcement of the Rock Shocks Trek race team on pink bike or the media outlets, our creative team did all the creative resources for that, and they did that half virtually and half through coming together. So we're able to still keep the bar pretty high and come up with cool content. Video production has taken a little bit of a hit, so we're having to, I mean this as a videographer and editor as well yourself, it's really hard to go on location and get content, whether it be through travel or personnel. And so we've had to rely a bit more on the editing of older content than the acquisition of new content. But again, creativity sometimes lies in the editing hand, and so we've been able to stay fresh. Some of our video shoots have gone from teams to one or two. We just had to just shift a little bit, but it's a really talented team, and so they're able to rise to the occasion.\n\nCole Heilborn (33:02): Yeah, well, I feel like if there's any time that stock sites are going to take off, this will be the time.", "token_estimate": 532, "speakers": ["David Zimberoff", "Cole Heilborn"], "start_timestamp": "30:31", "end_timestamp": "33:02", "podcast_index": 61, "episode_name": "EP 61: David Zimberoff | Leadership & Spending Brand Culture | SRAM", "slug": "ep-61-david-zimberoff-leadership-spending-brand-culture-sram-bb20e", "web_url": "https://www.portsidepro.com/podcast-feed/ep-61-david-zimberoff-leadership-spending-brand-culture-sram-bb20e", "guest_name": "David Zimberoff", "guest_title": "VP of Marketing, SRAM", "categories": [], "short_description": "The challenges of leading a marketing team while working remotely", "podcast_length": "44:83"}, {"id": "75d5bf4a-3016-4d7a-9e72-516ec1f989df", "episode_id": "d058428f-f662-4d1f-aa49-5ff24f16cac3", "cms_item_id": "68225dfc7bb476527f8c4862", "chunk_index": 15, "content": "David Zimberoff (33:07): Yeah, right. Stock video sites or stock photography, for sure.\n\nCole Heilborn (33:11): Yeah. So as your role, you've gone through pretty much the entire process and fulfilled every role in the marketing department in some capacity, but just with your history there, but now is your role as one of the leaders and just looking at the landscape and the environment that you're in and the culture that you guys still do have, I guess, what are the biggest things that you get excited about and what are the things that you're most concerned about from this position at the helm looking forwards?\n\nDavid Zimberoff (33:49): Deep down, Cole, I am a creative, and so a lot of times the biggest challenge for me is developing breakthrough, creative and continuing to raise the bar. That's a big one for me. And so trying to keep the team motivated in search of the greatest way to message or image our new product launches to get the attention and excitement of our riders. That's kind of number one. So because I feel like, and you've probably heard this before through books or seminars, that in order to have a conversation with somebody, you have to first get their attention and how do you get their attention either through film or message or color or whatever. And so really trying to sharpen the acts to messaging and identity building is paramount for us. That's the department we work in, and that's core to some of my upbringing. And so that's number one. The second would be just really the transfer of knowledge to the team and making sure that the team is delegated and empowered. Clearing the way, my role as a leader is to for sure challenge the status quo and make sure that our creative is at the top of its game, but making sure that my team has all the resources they need, whether it's time, money, people, you name it. Ultimately, that's my job to clear the way and let them run.\n\nCole Heilborn (35:36): Do you feel like just the work culture, the work from home culture that we're in now is impacting those creative breakthrough moments?", "token_estimate": 520, "speakers": ["David Zimberoff", "Cole Heilborn"], "start_timestamp": "33:07", "end_timestamp": "35:36", "podcast_index": 61, "episode_name": "EP 61: David Zimberoff | Leadership & Spending Brand Culture | SRAM", "slug": "ep-61-david-zimberoff-leadership-spending-brand-culture-sram-bb20e", "web_url": "https://www.portsidepro.com/podcast-feed/ep-61-david-zimberoff-leadership-spending-brand-culture-sram-bb20e", "guest_name": "David Zimberoff", "guest_title": "VP of Marketing, SRAM", "categories": [], "short_description": "The challenges of leading a marketing team while working remotely", "podcast_length": "44:83"}, {"id": "ca40d4c5-a4f0-4af6-9e32-272be5b0b08d", "episode_id": "d058428f-f662-4d1f-aa49-5ff24f16cac3", "cms_item_id": "68225dfc7bb476527f8c4862", "chunk_index": 16, "content": "David Zimberoff (35:45): Not yet. I haven't seen it, no. So we have a lot of great partners as well. We do a lot of great stuff internally, and we are partnered with a few creative agencies. Each one of our brands typically aligns themselves with a third party creative group. And no, I haven't seen, we have not slowed down. I mean, if anything, and you didn't touch on this and I'm hoping you won't, but just the whole challenge in the bike industry with supply chain and lead times, that's the only thing that's really slowed us down, but those things are completely out of our hands in terms of creativity and messaging and product innovation. We are nailing it.\n\nCole Heilborn (36:26): That's got to be pretty encouraging. I feel like despite everything for you is you're kind of looking at how the team is performing. I feel like it could be so much worse.\n\nDavid Zimberoff (36:36): For sure. Yeah. I mean, we had no idea that this pandemic would impact the bike industry or the outdoor industry as it did. And so we couldn't be more fortunate not only to have a highly performing team, but in a category that's performing really well despite the global economy of this pandemic, I mean is with hundreds of thousands of people that have passed away from it or the industries that have been severely impacted, like commercial real estate and travel, et cetera, food, retail. It's been devastating. I have family and friends in many of those categories, and they look at me like, oh my God, you guys hit the lottery. So it's a bit weird to have this. So we also try to be super sensitive to all those around us because it could have equally impacted the bike industry this way. Right?\n\nCole Heilborn (37:46): Sure, sure. What about Schram's culture that you guys have built over the last, I don't know, 20 years, 10 years has allowed you guys to remain this strong going remote?", "token_estimate": 471, "speakers": ["David Zimberoff", "Cole Heilborn"], "start_timestamp": "35:45", "end_timestamp": "37:46", "podcast_index": 61, "episode_name": "EP 61: David Zimberoff | Leadership & Spending Brand Culture | SRAM", "slug": "ep-61-david-zimberoff-leadership-spending-brand-culture-sram-bb20e", "web_url": "https://www.portsidepro.com/podcast-feed/ep-61-david-zimberoff-leadership-spending-brand-culture-sram-bb20e", "guest_name": "David Zimberoff", "guest_title": "VP of Marketing, SRAM", "categories": [], "short_description": "The challenges of leading a marketing team while working remotely", "podcast_length": "44:83"}, {"id": "cbd58ed5-b677-4e7c-ba9e-24ea57e4213f", "episode_id": "d058428f-f662-4d1f-aa49-5ff24f16cac3", "cms_item_id": "68225dfc7bb476527f8c4862", "chunk_index": 17, "content": "David Zimberoff (38:04): It's just one word people. We have really focused on recruiting great people and investing in those people. And if you do that and you empower those people with the tools they need to get the job done in an environment that they're happy, it's the people that have gotten us through this without that innovation comes from people. I'll throw out a fun book club recommendation that many of us have just powered through Creativity Inc.\n\nCole Heilborn (38:38): Classic.\n\nDavid Zimberoff (38:40): Do you know that one?\n\nCole Heilborn (38:41): I've read it a couple times. Yeah,\n\nDavid Zimberoff (38:44): It's so good. And so it's the story of Pixar and how they manage their business through how they manage a creative business. And it's just fascinating. But in the end, it boils down to the people. The Pixar story is cool because they're all about the story, but it's the people that write those stories. It's the people that make those stories. It's the people that direct those stories that really matter, because without people, you don't have any of it. So build a great team and you can survive anything.\n\nCole Heilborn (39:19): This is a sidebar conversation, but I was introduced to a gentleman who works at Pixar. He's one of the creative directors for one of their departments, actually as a candidate for this show. And we got to talking and we realized it probably wasn't the best fit for a number of different reasons, but it was so cool because he's been there for a number of years. He was there when Steve Jobs was involved. He was there during notes day, and so I had read Creativity Inc. Put it on the shelf, and I was like, this is gold. And then had the opportunity just to talk to this gentleman who had been there through all of those giant kind of milestone moments that are in the book. And needless to say, I was nerding out pretty hard, but for anyone who hasn't read the book it, it's really pretty incredible just learning how a great institution manages and works with people and promotes great storytelling and", "token_estimate": 516, "speakers": ["David Zimberoff", "Cole Heilborn"], "start_timestamp": "38:04", "end_timestamp": "39:19", "podcast_index": 61, "episode_name": "EP 61: David Zimberoff | Leadership & Spending Brand Culture | SRAM", "slug": "ep-61-david-zimberoff-leadership-spending-brand-culture-sram-bb20e", "web_url": "https://www.portsidepro.com/podcast-feed/ep-61-david-zimberoff-leadership-spending-brand-culture-sram-bb20e", "guest_name": "David Zimberoff", "guest_title": "VP of Marketing, SRAM", "categories": [], "short_description": "The challenges of leading a marketing team while working remotely", "podcast_length": "44:83"}, {"id": "77982628-622b-4d06-b4ff-47dba8b758c6", "episode_id": "d058428f-f662-4d1f-aa49-5ff24f16cac3", "cms_item_id": "68225dfc7bb476527f8c4862", "chunk_index": 18, "content": "David Zimberoff (40:15): Creativity. One of the things that resonated a lot with us at SRAM is we have actually a vice president of continuous improvement, and that VP has a 10 person department, and they are solely focused on continuous improvement around our organization, both from manufacturing process to business process. Creativity Inc talks a lot about continuous improvement, how it's all about removing waste from the value stream and optimizing things. And so the fact that here, the story of Pixar was talking about the continuous improvement opportunities that they had really validated for us how valuable continuous improvement could be. So we were super excited to learn about that. If nothing else, if you don't read Creativity Inc and get some business process advice out of it, you'll just love the story of Pixar, right? I mean, it's just a cool story.\n\nCole Heilborn (41:23): I think it helps you appreciate even more the work that they do.\n\nDavid Zimberoff (41:27): Totally.\n\nCole Heilborn (41:28): Yeah. Are there any other companies or any other leaders that you look at currently who you respect for the work that they're doing to try to maintain and build company culture? It could be in the outdoor world or not.\n\nDavid Zimberoff (41:49): I feel like I've been so living in this bubble coal that I don't even have windows in my basement. I'll share one just to share a related topic. We love continuous education and continuous improvement and self-help, et cetera. There's two marketing thought leaders that we like a lot that I'm sure some of you have heard of or seen or follow. And one that jumps to our forefront often is Simon ek. We really, really like what he's doing and some of what he shares and teaches. We also a little bit more controversial is Scott Galloway. I'm\n\nCole Heilborn (42:42): Familiar with that.", "token_estimate": 463, "speakers": ["David Zimberoff", "Cole Heilborn"], "start_timestamp": "40:15", "end_timestamp": "42:42", "podcast_index": 61, "episode_name": "EP 61: David Zimberoff | Leadership & Spending Brand Culture | SRAM", "slug": "ep-61-david-zimberoff-leadership-spending-brand-culture-sram-bb20e", "web_url": "https://www.portsidepro.com/podcast-feed/ep-61-david-zimberoff-leadership-spending-brand-culture-sram-bb20e", "guest_name": "David Zimberoff", "guest_title": "VP of Marketing, SRAM", "categories": [], "short_description": "The challenges of leading a marketing team while working remotely", "podcast_length": "44:83"}, {"id": "ae84c764-6260-41c0-bc7f-b00b5108a4fc", "episode_id": "d058428f-f662-4d1f-aa49-5ff24f16cac3", "cms_item_id": "68225dfc7bb476527f8c4862", "chunk_index": 19, "content": "David Zimberoff (42:43): Scott Galloway, AKA, professor G, look him up. So he has a continuous education or online education company called Section Four, and they teach brand strategy and product strategy. He's a super provocative, articulate marketing thought leader. He is a marketing strategy leader at a New York University stern business school. And so we've been taking some online classes through his company to further advance our or to sharpen our acts. We think we're good, but we can always do better in that spirit of continuous improvement. So back to your question, we like Simon Sinek. We like Scott Galloway. Of course, we like many of the brand leaders around the world, but those two for me, they just resonate sort of timely and we're watching them.\n\nCole Heilborn (43:47): Yeah. How do you make sure that you're continuing to learn and not getting stagnant?\n\nDavid Zimberoff (43:55): Well, so the example with Scott Galloway is actually next week we're starting, a, 12 of us are going to do a two week class with him, and I'm in there. So I'm basically dragging 11 of my team members with me to do this class together. And so side by side, I learned through activities like that, and I learn from my team every day too. They always say, you should hire people that are smarter than you. So all I really have to do is listen to my team and I learn shit all the time. Online education is certainly going to help that, and we're always in search of learning what we can do better or what we can learn that we don't already know.\n\nCole Heilborn (44:45): Well, that's encouraging. I think this entire conversation has been really interesting. I think at the bottom of it, it's been encouraging for me to know that there are brands out there who are able to still do well, produce good work, have strong company morale. So I guess well done.\n\nDavid Zimberoff (45:04): It can happen. Yeah. Thanks a lot.", "token_estimate": 479, "speakers": ["David Zimberoff", "Cole Heilborn"], "start_timestamp": "42:43", "end_timestamp": "45:04", "podcast_index": 61, "episode_name": "EP 61: David Zimberoff | Leadership & Spending Brand Culture | SRAM", "slug": "ep-61-david-zimberoff-leadership-spending-brand-culture-sram-bb20e", "web_url": "https://www.portsidepro.com/podcast-feed/ep-61-david-zimberoff-leadership-spending-brand-culture-sram-bb20e", "guest_name": "David Zimberoff", "guest_title": "VP of Marketing, SRAM", "categories": [], "short_description": "The challenges of leading a marketing team while working remotely", "podcast_length": "44:83"}, {"id": "c8c6f3ae-fc24-4c6d-99b9-9d5e260d2617", "episode_id": "d058428f-f662-4d1f-aa49-5ff24f16cac3", "cms_item_id": "68225dfc7bb476527f8c4862", "chunk_index": 20, "content": "Cole Heilborn (45:07): Yeah. We're about out of time for today, but if people want to follow along with you, if people want to follow along with the company or if you have any recommendations for resources that you have found valuable around this conversation, where can people go to learn more?\n\nDavid Zimberoff (45:24): So to learn more about sram, obviously sram.com is the first spot. Personally, I don't personally do a lot of social media work. I do have a LinkedIn account, but unfortunately I think it's full right now. I think I've maxed out and I can't actually add anyone.\n\nCole Heilborn (45:47): Is that a thing?\n\nDavid Zimberoff (45:47): But if you find, yeah, they max out at 30,000,\n\nCole Heilborn (45:51): Do they really? I didn't know that.\n\nDavid Zimberoff (45:53): Yeah, you cannot have more than 30,000 people. So unfortunately, I've had an account so long that, and I think at one point I just accepted if you were in the outdoor industry. I'm like, yeah, you're in. So now I've tapped out. But occasionally a spot opens because somebody terms out or somebody ops out. So my account hovers between 29, 9, 9, 8, and 30,000 monthly. So if you find me on LinkedIn, it's David Zi. If a spot opens up, I'll accept you as a link.\n\nCole Heilborn (46:26): It's nothing personal.\n\nDavid Zimberoff (46:27): Yeah. Our Instagrams, ATRA Road, atra, MTB at Rocks, shocks at zip speed, those are great. Instagram's a great, great place. butra.com is the best starting point.\n\nCole Heilborn (46:41): Okay. And any resources that you'd recommend other than Simon Sinek or Creativity Inc. For folks?\n\nDavid Zimberoff (46:47): Yeah, I mean, I would add Scott Galloway to that list, those three, there's some fascinating stuff. We love almost the entire TED Talk community as well, so I don't have, other than Simon Sinek's TED Talk, I don't have one that jumps out, but we love Ted Talks, and that'd be the only other one. Yeah, creativity Inc is an awesome one. I'm trying to think of the last other book that I read that I loved. No, that's it.", "token_estimate": 512, "speakers": ["Cole Heilborn", "David Zimberoff"], "start_timestamp": "45:07", "end_timestamp": "46:47", "podcast_index": 61, "episode_name": "EP 61: David Zimberoff | Leadership & Spending Brand Culture | SRAM", "slug": "ep-61-david-zimberoff-leadership-spending-brand-culture-sram-bb20e", "web_url": "https://www.portsidepro.com/podcast-feed/ep-61-david-zimberoff-leadership-spending-brand-culture-sram-bb20e", "guest_name": "David Zimberoff", "guest_title": "VP of Marketing, SRAM", "categories": [], "short_description": "The challenges of leading a marketing team while working remotely", "podcast_length": "44:83"}, {"id": "fb28a048-d233-410c-ab82-99548a9bfb6d", "episode_id": "d058428f-f662-4d1f-aa49-5ff24f16cac3", "cms_item_id": "68225dfc7bb476527f8c4862", "chunk_index": 21, "content": "Cole Heilborn (47:16): Okay, great. Well, David, I appreciate you taking the time to chat and share a little bit about your history with the company and kind of again, shed some light of encouragement to I think folks who are probably feeling a little frustrated with how things are going.\n\nDavid Zimberoff (47:30): For sure. Well, it's been great talking to you, Cole.\n\nCole Heilborn (47:32): Yeah, thank you. And have a good rest of your day.\n\nDavid Zimberoff (47:34): Thanks, you too.\n\nCole Heilborn (47:35): See you. Thank you for listening to this episode of the Backcountry Marketing Podcast. If you enjoyed today's episode or learn something new, please consider leaving us a review on Apple or sharing this with a friend.", "token_estimate": 183, "speakers": ["Cole Heilborn", "David Zimberoff"], "start_timestamp": "47:16", "end_timestamp": "47:35", "podcast_index": 61, "episode_name": "EP 61: David Zimberoff | Leadership & Spending Brand Culture | SRAM", "slug": "ep-61-david-zimberoff-leadership-spending-brand-culture-sram-bb20e", "web_url": "https://www.portsidepro.com/podcast-feed/ep-61-david-zimberoff-leadership-spending-brand-culture-sram-bb20e", "guest_name": "David Zimberoff", "guest_title": "VP of Marketing, SRAM", "categories": [], "short_description": "The challenges of leading a marketing team while working remotely", "podcast_length": "44:83"}, {"id": "86eee845-cf77-40e4-bef4-9528c0c5ad01", "episode_id": "6c349e21-fb5e-4e13-83d4-459a9ed8ae26", "cms_item_id": "68225dfc7bb476527f8c4867", "chunk_index": 0, "content": "Chase White (00:00:01): What results are they trying to drive for their boss, right in supporting the business as a business person, not just as a shooter or a designer or a producer. Thinking of it with the business head on I think is a huge one. And if you can find all of those things together, I think you're going to get better results than you would get with an agency, and you're going to get it much quicker and you're going to get much cheaper.\n\nCole Heilborn (00:00:33): Welcome to the Backcountry Marketing podcast. My name is cool and I'll be your host today. This podcast dives deep with leaders of the outdoor marketing industry as they discuss the gritty details of their work, personal challenges and latest adventures, whether you're standing in the lift line, shuttling to fresh loam or cracking a local beer. I hope you enjoyed today's episode. This is the Back Country Marketing Podcast. This episode is produced by Portside Productions, an outdoor, commercial and film production company based in the Pacific Northwest. Welcome to the Backcountry Marketing Podcast. My name is Cole Hoborne. Today I'm sitting down with Chase White. He's a commercial and editorial photographer based out of Squamish, bc. Chase. How are you?\n\nChase White (00:01:16): I'm good, Cole. How are you doing, man?\n\nCole Heilborn (00:01:18): Doing awesome. I'm excited for the day when I can visit Squamish because it's not that far away.\n\nChase White (00:01:25): Same man. There's a lot of people we're looking to get up here. I mean, safe to say we've had a crazy tourism hit, but friends and family are included in that as well, so we're looking forward to getting the borders open soon.\n\nCole Heilborn (00:01:38): Are you one of the locals that enjoys the tourists like me coming up and hanging out in Squamish or do you prefer to keep it locals only?", "token_estimate": 463, "speakers": ["Chase White", "Cole Heilborn"], "start_timestamp": "00:00:01", "end_timestamp": "00:01:38", "podcast_index": 62, "episode_name": "EP 62: Chase White | Contract Creatives in 2021 | Chase White Photography", "slug": "ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "guest_name": "Chase White", "guest_title": "Creative Director, Chase White Photography", "categories": [], "short_description": "How clients and contractors can work best together to produce meaningful work.", "podcast_length": "44:84"}, {"id": "3808e2b3-969b-4606-a76c-f9cc8d2cb55b", "episode_id": "6c349e21-fb5e-4e13-83d4-459a9ed8ae26", "cms_item_id": "68225dfc7bb476527f8c4867", "chunk_index": 1, "content": "Chase White (00:01:47): Man, I would love to selfishly keep it locals only, but the reality is as a commercial photographer being out here, I work with a lot of tourist space companies, so that could be fishing guide services or outdoor lodges, and they've just been hit brutally hard by the closures and they're just hanging by a thread. So I got a side with the homies there and say, let's get 'em open. I actually just got done working on a film that touches on that quite a bit, and it's kind of centered around the impact of COVID on the outdoor industry specific to sort of the fly fishing community in northern British Columbia. And it's actually going to be featured in the fly fishing film tour, which goes live today as we record this, so\n\nCole Heilborn (00:02:37): Oh,\n\nChase White (00:02:37): Awesome. It's a leap year and definitely take some time to check it out if you're so inclined.", "token_estimate": 225, "speakers": ["Chase White", "Cole Heilborn"], "start_timestamp": "00:01:47", "end_timestamp": "00:02:37", "podcast_index": 62, "episode_name": "EP 62: Chase White | Contract Creatives in 2021 | Chase White Photography", "slug": "ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "guest_name": "Chase White", "guest_title": "Creative Director, Chase White Photography", "categories": [], "short_description": "How clients and contractors can work best together to produce meaningful work.", "podcast_length": "44:84"}, {"id": "d1c76599-a7ed-4b09-b2f7-3f7487ba2c9b", "episode_id": "6c349e21-fb5e-4e13-83d4-459a9ed8ae26", "cms_item_id": "68225dfc7bb476527f8c4867", "chunk_index": 2, "content": "Cole Heilborn (00:02:43): Definitely. Well, I'm excited for our conversation today. I think just to set the table for kind what we're going to be chatting about, we're going to dive into the relationship between contract creatives and the clients, the marketing folks, whether that's agency or brand side. And Chase, you and I kind of originally connected over a number of things, but this was definitely one of the topics that I feel like we both really enjoyed talking about. And so I'm looking forward to bringing this conversation to the audience. And I guess just to quickly outline why we're talking about this, there's a lot of, I mean, contractors are everywhere in the industry. You're one, we're one, and there's some really great things that can come out of the relationship between the contractor and the client. I also feel like there's a little bit of a stereotype, a little bit of bad blood maybe around the contractor and the client. (00:03:41): And just on the contractor side, I feel like we've all heard the stories about the client who's sending you texts at 1:00 AM asking for revisions and their nickel and dimming on budget and making unreasonable timelines. On the flip side, the client, I feel like they hire a contractor, the contractor just takes the money and runs and just does whatever they want, and then they show up three months later above budget and late, and they just kind of give the client whatever they made and the client's like, I don't even know what to do with this. So I'm hoping we can kind of talk about how do clients, what's the optimal relationship between clients and contractors and kind of use your experience in the industry and your perspective to hopefully educate both sides of that party. So to kind of jump in, could you give us a little bit of a background on yourself as a photographer and how you got into it?", "token_estimate": 468, "speakers": ["Cole Heilborn"], "start_timestamp": "00:02:43", "end_timestamp": "00:02:43", "podcast_index": 62, "episode_name": "EP 62: Chase White | Contract Creatives in 2021 | Chase White Photography", "slug": "ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "guest_name": "Chase White", "guest_title": "Creative Director, Chase White Photography", "categories": [], "short_description": "How clients and contractors can work best together to produce meaningful work.", "podcast_length": "44:84"}, {"id": "ec2137bf-ae85-48ab-a704-5709ba50c26e", "episode_id": "6c349e21-fb5e-4e13-83d4-459a9ed8ae26", "cms_item_id": "68225dfc7bb476527f8c4867", "chunk_index": 3, "content": "Chase White (00:04:41): Yeah, totally. I'm a sort of self-proclaimed reform startup tech person who has just always been really passionate about exploring the outdoors personally. And I sort of sharpened my creative teeth deep in the design and product design worlds of software. And there's a lot of overlap there that you surprisingly wouldn't think. But growing up in south Texas, I went to school for fine art and business, and after graduating I found myself idolizing the nexus of creativity in business as it transpires in the agency world. I found myself just really looking up to these really, really cool California agencies where it's like the 72 and the Chiat days and all these people out there working on really rad apple campaigns and things like that. I just thought those people hung the moon, and I was like, I'll do whatever I need to do to get into that. (00:05:55): That just looks like a really rad lifestyle. And so that's kind of how I sort of vision my direction for myself. And right out of college, I started working for a branding and marketing agency out of San Antonio, and the amount of experience that I got there was just priceless. And I would say for myself personally, it was just infinite of being put on emerging accounts, food and beverage, all kinds of fun stuff like inception, businesses, everything. And that was, I think that was like 2007, 2008. So it was kind of like a lot of really cool things were happening in media then a lot of modern day media as we know it was being birthed then. And for me, that sort of jumped into more of design software product design personally. And I took a job as a creative director for a publicly traded software company up in Austin, Texas and Austin being such a creative tech hub, it was a great place to spend 10 years of my life sort of growing into a polished professional in the creative space. (00:07:15): And from there I started two technology startups and both of 'em resulted in exits one way or another, which it gave me a bit of a platform to jump into my next chapter. And I had always had an incredible amount of respect and admiration for creative contractors. And I found myself being in a position where I was like, okay, well be very intentional about what you want to do with your life next. And that's what I did. And as somebody who had freelanced on the side for as a creative doing photography and design and creative consulting, I just jumped in full steam. And around that same time, a little bit before it, I met my now wife who lives who lived in Vancouver. And so we did long distance for a while, but eventually made the jump to the great white north and got into some really rad projects up here that just lit a fire under me to just go deeper and deeper into the creative contractor space. And I'm just proud of all the projects that I get to work on and haven't really looked back since. I'm just a happy camper over here.", "token_estimate": 735, "speakers": ["Chase White"], "start_timestamp": "00:04:41", "end_timestamp": "00:04:41", "podcast_index": 62, "episode_name": "EP 62: Chase White | Contract Creatives in 2021 | Chase White Photography", "slug": "ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "guest_name": "Chase White", "guest_title": "Creative Director, Chase White Photography", "categories": [], "short_description": "How clients and contractors can work best together to produce meaningful work.", "podcast_length": "44:84"}, {"id": "67d82d48-ff5d-4ed3-ae6c-ace5de7d6298", "episode_id": "6c349e21-fb5e-4e13-83d4-459a9ed8ae26", "cms_item_id": "68225dfc7bb476527f8c4867", "chunk_index": 4, "content": "Cole Heilborn (00:08:36): So when did you pick up the camera first though?\n\nChase White (00:08:41): That's a long one. I mean, I studied photography in high school and then studied photography in college as well, so I sharpened my teeth in a traditional dark room setting. And then nowadays, I'm not the tweed cap influencer film photographer, but I definitely keep a few cameras on deck at all times. But it's honestly been a lifelong thing since high school.\n\nCole Heilborn (00:09:16): I feel like the contract creative sounds like an idyllic, this is where we added\n\nChase White (00:09:23): Idyllic, maybe\n\nCole Heilborn (00:09:24): Idyllic. Yeah, I feel like the contract creative just seems like this perfect life balance where you can do whatever you want, you only get to work on things you enjoy, and there's definitely some of those pros to it. Paint us a picture of some of the good things that come along with being a contract creative and some of the things that maybe other folks don't realize or isn't talked about.", "token_estimate": 258, "speakers": ["Cole Heilborn", "Chase White"], "start_timestamp": "00:08:36", "end_timestamp": "00:09:24", "podcast_index": 62, "episode_name": "EP 62: Chase White | Contract Creatives in 2021 | Chase White Photography", "slug": "ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "guest_name": "Chase White", "guest_title": "Creative Director, Chase White Photography", "categories": [], "short_description": "How clients and contractors can work best together to produce meaningful work.", "podcast_length": "44:84"}, {"id": "198431ca-4ead-4a76-bef7-385092e97fd0", "episode_id": "6c349e21-fb5e-4e13-83d4-459a9ed8ae26", "cms_item_id": "68225dfc7bb476527f8c4867", "chunk_index": 5, "content": "Chase White (00:09:48): Totally. Yeah, no, it's really cool. And honestly cool. I'm super excited to be talking about this with you on the podcast because it's something that I personally haven't been able to find anyone talking about anywhere else. It's certainly, I think it goes under the radar a lot because I wish I knew what the actual status for you, but today the percentage of creatives who are contractors is just staggering. So it affects a lot of people both on the brand side, in the agency world and on the actual contractor side. So it's a cool thing to bring more light to, but I think the obvious ones are the flexibility that you get when you are a contract creative. You can choose when you want to work, you can choose what you want to work on, you can choose what mediums you want to focus on. And it's not to say you can't really do that in an agency. (00:10:44): I think you can on some level, but it doesn't give you that full autonomy that being a true contractor in your own right does. But that said, there's ups and downs to everything. And being a contract creative I think is no different. The biggest one that stands out is the consistency of your income, depending on your standing in life, wherever you're at, it's not for everybody. And I'm in no way recommending it as this great thing that everyone should try to do because that uncertainty of your biz dev funnel, it's a real thing and it's always happening. No matter the best shooters in the world, same thing happens to them. So it's all relative in that sense. But you're also doing everything right. You're the accounting department, you're the sales department, you are the put out fires department, you, you're a producer, you're a director, you're everything, and you can kind of develop small teams, but then you start getting into that agency world. So it's a unique thing, not for the faint of heart, but if it is right for you, it's incredibly rewarding.", "token_estimate": 489, "speakers": ["Chase White"], "start_timestamp": "00:09:48", "end_timestamp": "00:09:48", "podcast_index": 62, "episode_name": "EP 62: Chase White | Contract Creatives in 2021 | Chase White Photography", "slug": "ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "guest_name": "Chase White", "guest_title": "Creative Director, Chase White Photography", "categories": [], "short_description": "How clients and contractors can work best together to produce meaningful work.", "podcast_length": "44:84"}, {"id": "f7787bc7-e361-4f27-a15a-a419707a5d75", "episode_id": "6c349e21-fb5e-4e13-83d4-459a9ed8ae26", "cms_item_id": "68225dfc7bb476527f8c4867", "chunk_index": 6, "content": "Cole Heilborn (00:12:09): So maybe before we go deeper, let's define contract creative. Do you see that as being one person? You mentioned as you start to work with more and more people, you start to bleed into that agency definition. To you, what is a contract creative?\n\nChase White (00:12:26): I think a contract creative personally is somebody who for the most part, most part, works autonomously. There are people that I have fantastic relationships with that I'll team up with on projects, but it's not a fixed team of people that we collectively are always bringing each other in on every project. The majority of my work is just myself, and I think it's an interesting idea to kind of erupt. Why is that? Why would you prefer to work by yourself? And some people just like to work fast. I like to work fast. If you want to go fast, go alone. If you want to go far, go together. And I like working fast, man.\n\nCole Heilborn (00:13:10): One question that I hear pop up a lot is why work with a contract creative? I feel like the creative industry is at a really interesting place now where a lot of brands are bringing creatives in-house to develop their own internal teams. Agencies are doing a hybrid of a lot, bringing in contractors, building out their own internal teams. I guess first, why would anyone want to work with someone like yourself?", "token_estimate": 339, "speakers": ["Cole Heilborn", "Chase White"], "start_timestamp": "00:12:09", "end_timestamp": "00:13:10", "podcast_index": 62, "episode_name": "EP 62: Chase White | Contract Creatives in 2021 | Chase White Photography", "slug": "ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "guest_name": "Chase White", "guest_title": "Creative Director, Chase White Photography", "categories": [], "short_description": "How clients and contractors can work best together to produce meaningful work.", "podcast_length": "44:84"}, {"id": "9fc4968b-54ba-405f-99dc-ec7d065bb734", "episode_id": "6c349e21-fb5e-4e13-83d4-459a9ed8ae26", "cms_item_id": "68225dfc7bb476527f8c4867", "chunk_index": 7, "content": "Chase White (00:13:42): I think, well, personally I get a lot of flexibility from my position. I think from a brand or an agency side, you also adopt a lot of flexibility in working with somebody like that. You can pop in and hire them when you want to hire them, and then you can pop out and touch base in a couple months or whatever. You don't have to maintain that constant overhead of having that person on full staff. And today's day and age, I think there's a lot of resources that previous generations didn't have to support yourself with. Things like healthcare solutions, insurance, whatever, a lot of things like that that are now more available to a contractor to hold that lifestyle in a healthy way. But I think it just provides flexibility for everybody. And then it's like as a brand, as an outdoor brand in 2021, you're not always working on the same thing. (00:14:47): It's not just the same project over and over again. You may be a brand that's working on a mountain biking shoot this day and then next week you're working on something that's a fly fishing shoot. And the reality is an in-house person working for your brand full-time may not be the right person to work on both of those. And so I think it gives you an added ability of having some really nice sort of passionate specificity in who you're putting on what projects so that you're really kind of getting somebody on them who understands all the nuances of them and is proficient and knows all the kind of details and storylines that can happen in any given project like that. So I think you get a lot of flexibility on both ends.", "token_estimate": 404, "speakers": ["Chase White"], "start_timestamp": "00:13:42", "end_timestamp": "00:13:42", "podcast_index": 62, "episode_name": "EP 62: Chase White | Contract Creatives in 2021 | Chase White Photography", "slug": "ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "guest_name": "Chase White", "guest_title": "Creative Director, Chase White Photography", "categories": [], "short_description": "How clients and contractors can work best together to produce meaningful work.", "podcast_length": "44:84"}, {"id": "9de15cec-498e-4ee8-a642-f9109cbbcfd8", "episode_id": "6c349e21-fb5e-4e13-83d4-459a9ed8ae26", "cms_item_id": "68225dfc7bb476527f8c4867", "chunk_index": 8, "content": "Cole Heilborn (00:15:34): Yeah. How important is that, that specificity, when you hire someone like yourself, you're an avid fly fisher if a fly fishing company brings you in, you obviously know that world and you can make sure it's real and it's authentic and everything that you're capturing is legit. Someone who maybe isn't as in tune with that is brought in. Maybe they don't capture those authentic moments like you would, but how important is that? Can that person who doesn't know the depth of that sport or that focus, can they learn those things and then output a product that's just as good or still capture that same level of authenticity?\n\nChase White (00:16:15): Yeah, I think it's a great question and such a cool sort of idea to mull around because I think while it's, in no way do I mean this as a hundred percent rule, I think there are definitely exceptions, but I think if you're just take for example, if you're a climbing company and you hire somebody who's never climbed before, and granted I'm dealing in extremes here, but just to make a point, somebody who doesn't climb, they don't know all those moments to one, anticipate them coming down the pipeline, oh, I got to be right here. When that person tops out on the route for that big emotional reaction, I've got to be there. And knowing even tactically where that person, where they're going to fall if they take a whip or whatever, things like that that are like, there's a lot that goes into outdoor adventures that a lot of people don't think about. (00:17:12): We're not always dealing with some friendly fake hike. There's a lot of real tactfully stuff. Just the other day I was on a shoot where we're rafting down a whitewater river for a fly fishing shoot and it's like you can't just put anyone in that position. And if you do, I think you're bound to not only not nail it, but you're going to miss some key opportunities. So just like with the climbing example, I think you're really just going to ensure the best results if you get somebody who's personally passionate about that outdoor pursuit who happens to also be a strong creative.", "token_estimate": 532, "speakers": ["Cole Heilborn", "Chase White"], "start_timestamp": "00:15:34", "end_timestamp": "00:16:15", "podcast_index": 62, "episode_name": "EP 62: Chase White | Contract Creatives in 2021 | Chase White Photography", "slug": "ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "guest_name": "Chase White", "guest_title": "Creative Director, Chase White Photography", "categories": [], "short_description": "How clients and contractors can work best together to produce meaningful work.", "podcast_length": "44:84"}, {"id": "d690e673-b49e-4573-a495-c5bd03efe4d9", "episode_id": "6c349e21-fb5e-4e13-83d4-459a9ed8ae26", "cms_item_id": "68225dfc7bb476527f8c4867", "chunk_index": 9, "content": "Cole Heilborn (00:17:51): So to go a little further into that, this is something I've thought a lot about and in fact some of the conversations we've had on the show, actually it hasn't come out yet with an agency. We talked a lot about how does an agency make sure that they're creating authentic content. I think what you're describing here is authenticity and they have an entire process built out to, if they don't know what makes the sport or the activity, what are those authentic moments? They have an entire process, this process that they use to figure that out. I dunno, just curious to hear your reaction to something like that because I think there are people who realize, oh, I don't know how to do this, but I have ways that I know I'm going to figure out how to do it and what are the important things to capture.\n\nChase White (00:18:40): Totally. And that's true too. And make no mistake about it, I don't only work in fly fishing. I mean, while I'm passionate about that, I think it makes it a nice niche for myself to be able to work on stuff that I particularly understand well. But there are oftentimes where I'm out doing a shoot where we're ski touring or we're mountain biking or other things, I would say that other group that catchall makes up for about half of my work. And I think as a contract creative, it's really tough in today's market to be able to just do one sport as you're, you just won't be able to really pay your bills if you just do one thing. You have to be able to diversify.\n\nCole Heilborn (00:19:30): Sure.\n\nChase White (00:19:31): But as for your question as an agency process on adopting and injecting credibility into their shoots, I think that's fine. I don't think that would've the same power as having somebody behind the lens or somebody producing who really does know it, but I'm sure it works in plenty of cases to get the job done.\n\nCole Heilborn (00:19:59): Yeah. Do you have an example of maybe a project that you took on where you weren't as familiar with the inner workings of the space and what was the outcome of that?", "token_estimate": 520, "speakers": ["Cole Heilborn", "Chase White"], "start_timestamp": "00:17:51", "end_timestamp": "00:19:59", "podcast_index": 62, "episode_name": "EP 62: Chase White | Contract Creatives in 2021 | Chase White Photography", "slug": "ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "guest_name": "Chase White", "guest_title": "Creative Director, Chase White Photography", "categories": [], "short_description": "How clients and contractors can work best together to produce meaningful work.", "podcast_length": "44:84"}, {"id": "c86526e6-a568-4bfe-a20d-71c3e6929f68", "episode_id": "6c349e21-fb5e-4e13-83d4-459a9ed8ae26", "cms_item_id": "68225dfc7bb476527f8c4867", "chunk_index": 10, "content": "Chase White (00:20:10): Man, I want to give you an example in the outdoors of that, but the examples that really do sort of authentically come to mind are when I'm shooting any project that's not in the outdoors, and I'm sorry for any client of mine that's listening right now, that's not an outdoors client, but it's like I am less inclined to celebrate the work myself, and I just find that when my own passion is lacking on the project, things take longer. I don't have that fire to really nail it. And that's a crazy thing to say publicly as somebody who likes having a full pipeline of work. But that's just the truth. And that comes back to finding the power of finding people who are passionate about the niche that your actual project is in. So for me, that kind of unfortunately falls in the realm of not outdoor sort of back country marketing esque projects. For me, those are the ones where I'm kind of like I'm not rushing back to offload my cards and go dig into the media. You know what I mean?\n\nCole Heilborn (00:21:30): Sure. Okay. You just brought up something super interesting and something that I feel like I've got a lot of questions about. So I'm just going to rattle through some, you pick what you want to respond to. Okay. So one, is it the client's expectation that the contractor always be over the moon and stoked for the project? I guess second, going through those projects for yourself, have you learned, has that influenced what you take on and what you say yes to? I dunno, let's start there.", "token_estimate": 382, "speakers": ["Chase White", "Cole Heilborn"], "start_timestamp": "00:20:10", "end_timestamp": "00:21:30", "podcast_index": 62, "episode_name": "EP 62: Chase White | Contract Creatives in 2021 | Chase White Photography", "slug": "ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "guest_name": "Chase White", "guest_title": "Creative Director, Chase White Photography", "categories": [], "short_description": "How clients and contractors can work best together to produce meaningful work.", "podcast_length": "44:84"}, {"id": "924c4291-85ec-4dd7-a2e7-2280fc293168", "episode_id": "6c349e21-fb5e-4e13-83d4-459a9ed8ae26", "cms_item_id": "68225dfc7bb476527f8c4867", "chunk_index": 11, "content": "Chase White (00:22:09): It does. It does big time because I think not all work is equal and not every dollar is equal. I particularly enjoy, I would rather make $1 doing something I love than to make $5 doing something that I find kind of dry and exhausting. I can't help. The moment that really gets me is take a big shoot. If I'm doing that in something that I'm not passionate about, people don't understand how much time goes into post-production and that's a lot of time where I'm going to be sitting there married to my computer, just going through it, making selects out of, on any given shoot, I can shoot upwards of anywhere from 2000 to 20,000 images. Culling that down takes a lot of time. And if you're trying to cu down something that you're just really not passionate about, it's tough, man. It's real tough.\n\nCole Heilborn (00:23:11): So is that your responsibility or the client's responsibility?\n\nChase White (00:23:18): I think that's the contractor's responsibility you have every right in the world to accept a job or not accept a job. And I think if you do accept a job and you are not going to bring your A game dude, that's on you. And I think you do owe your clients better than to mail something in.", "token_estimate": 306, "speakers": ["Chase White", "Cole Heilborn"], "start_timestamp": "00:22:09", "end_timestamp": "00:23:18", "podcast_index": 62, "episode_name": "EP 62: Chase White | Contract Creatives in 2021 | Chase White Photography", "slug": "ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "guest_name": "Chase White", "guest_title": "Creative Director, Chase White Photography", "categories": [], "short_description": "How clients and contractors can work best together to produce meaningful work.", "podcast_length": "44:84"}, {"id": "cf88fb65-934d-4d04-bdf0-74fa2d092aab", "episode_id": "6c349e21-fb5e-4e13-83d4-459a9ed8ae26", "cms_item_id": "68225dfc7bb476527f8c4867", "chunk_index": 12, "content": "Cole Heilborn (00:23:39): Something that I heard recently was a way to think about how you take on work. I think there's a bunch of different kind of formulas out there that people have put together that help you think through should I say yes to this job? One of them that I've always kind of looked at and used historically is time. What is it? The budget, the connections and the creative opportunity. And if you can hit two of those three, then that's a pretty solid choice. Another one that I heard recently that I feel like I'm going to add in addition to that filter is unless you can knock the project out of a park, you shouldn't take it. Which that got me really thinking. I was like, shoot, how many projects have I taken on that maybe I shouldn't have? And did we do the client the best job that we should have done or could have done? And it gets tricky, I feel like when you deal with your own personal passion for a project because you're like, well, I'm in business, I just need to do a good job all the time. But inevitably that personal level of interest I feel like greatly influences the quality of work that we're able to do.\n\nChase White (00:24:50): And I would take that a step further and just for the sake of exploring it, how would you apply that? If you're a really new shooter and you're trying to get experience by that theory, you shouldn't take any work, right?\n\nCole Heilborn (00:25:05): A hundred percent. And yeah, you should never push yourself. You should never take something that's outside your comfort zone.", "token_estimate": 387, "speakers": ["Cole Heilborn", "Chase White"], "start_timestamp": "00:23:39", "end_timestamp": "00:25:05", "podcast_index": 62, "episode_name": "EP 62: Chase White | Contract Creatives in 2021 | Chase White Photography", "slug": "ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "guest_name": "Chase White", "guest_title": "Creative Director, Chase White Photography", "categories": [], "short_description": "How clients and contractors can work best together to produce meaningful work.", "podcast_length": "44:84"}, {"id": "7a350d02-d912-4302-801e-b54617e0706b", "episode_id": "6c349e21-fb5e-4e13-83d4-459a9ed8ae26", "cms_item_id": "68225dfc7bb476527f8c4867", "chunk_index": 13, "content": "Chase White (00:25:13): And I think there's ways you can caveat your work and you can build an understanding with whatever marketing manager that you're working with and say, look, hey, this isn't something I've done before. I think I can do a really good job. Here's what I can ask of you that I think you can help support me in this. Here's how we can in the best way possible, get the results you're looking for without, while caveating it, Hey, I don't know. I haven't done this exactly before. I don't know that we're going to knock this out of the park, but here's what I'm willing to do. And you could even structure it with some sort of creative compensation where it's like, I think we're going to do a really good job, but in the event that we don't and you truly aren't satisfied with the results, we can just keep it at the deposit or something like that. But if you really like it and you want to use all of these assets, then we will go through the full amount. I think things like that, you can get creative and structure it, so it's like there's a bit of a safety net for people.\n\nCole Heilborn (00:26:17): Yeah, interesting. Flipping it around a little bit for the marketing manager or the individual in the agency who's looking at hiring a contractor for a project, what are things that they should consider? What are things that they should prioritize?", "token_estimate": 343, "speakers": ["Chase White", "Cole Heilborn"], "start_timestamp": "00:25:13", "end_timestamp": "00:26:17", "podcast_index": 62, "episode_name": "EP 62: Chase White | Contract Creatives in 2021 | Chase White Photography", "slug": "ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "guest_name": "Chase White", "guest_title": "Creative Director, Chase White Photography", "categories": [], "short_description": "How clients and contractors can work best together to produce meaningful work.", "podcast_length": "44:84"}, {"id": "885fec33-b301-4c60-9df7-0391e3053395", "episode_id": "6c349e21-fb5e-4e13-83d4-459a9ed8ae26", "cms_item_id": "68225dfc7bb476527f8c4867", "chunk_index": 14, "content": "Chase White (00:26:34): As somebody who's had brands before, and I've worked on all three sides of this gun, I've worked on the brand side, I've worked on the agency side, and I've worked on the contractor side. I think the number one thing that somebody should be looking for when they're hiring a contract creative is just a high level of creative integrity. (00:27:00): Is the level of work that they're putting out something that you think that they're personally proud of? Does it have a good amount of polish to it? Does it have punch to it? Are they proficient with the medium? Truly right? Do they have great control over their medium that they're going to be employing on your project? But I think creative integrity just as a notion is what I would look for first. Is this person executing at a really high level that I need on my project? I think that's a starting point, but as we've said before already, the second thing I go to is are they proficient in the actual task at hand of are they passionate about whatever it is we're doing? I think those are two really good starting points.\n\nCole Heilborn (00:27:58): How important is, I don't know, things that come after that, just basic business skills, communication skills, the ability to think strategically because I mean what you said there I feel like could be a client's biggest concern is they're super creative, but if they can't communicate and if they're not strategic, then they might just make something that they like and it doesn't actually help me.", "token_estimate": 382, "speakers": ["Chase White", "Cole Heilborn"], "start_timestamp": "00:26:34", "end_timestamp": "00:27:58", "podcast_index": 62, "episode_name": "EP 62: Chase White | Contract Creatives in 2021 | Chase White Photography", "slug": "ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "guest_name": "Chase White", "guest_title": "Creative Director, Chase White Photography", "categories": [], "short_description": "How clients and contractors can work best together to produce meaningful work.", "podcast_length": "44:84"}, {"id": "80d7c2a0-3caa-4b6b-9e2a-02c359f028bd", "episode_id": "6c349e21-fb5e-4e13-83d4-459a9ed8ae26", "cms_item_id": "68225dfc7bb476527f8c4867", "chunk_index": 15, "content": "Chase White (00:28:27): Yeah, no, I mean I think you nailed it there. That's one of the risks you take on as a brand by working with a contract creative that you wouldn't get with an agency. Like an agency is going to charge you, I don't know, 10 to 20 times as much as an individual contractor might, but they have a pretty solid fail safe program, a huge team of people that in the event that things fall apart, they're going to probably pick those up and put it back together. There's going to be a lot more sort of sifts for all these ideas to go through. So I think to your point, finding somebody that's going to work on your project that has that business acumen that can be an entrepreneur in themselves and be empathetic with your business, can they put the business hat on and think, how is my work going to affect the bottom line of this company? (00:29:29): How is my work going to make this marketing manager's life easier? How am I going to make them look good? What results are they trying to drive for their boss in supporting the business as a business person, not just as a shooter or a designer or a producer? Thinking of it with the business head on I think is a huge one. And if you can find all of those things to together, I think you're going to get better results than you would get with an agency and you're going to get it much quicker and you're going to get much cheaper.\n\nCole Heilborn (00:30:09): Why will it be better? Because in one hand, you're comparing a well organized machine that's capable of knocking out big campaigns with tons of resources. On the other hand, you've got potentially a scrappy individual who knows their niche really well, who's highly creative, but it's just one person.", "token_estimate": 433, "speakers": ["Chase White", "Cole Heilborn"], "start_timestamp": "00:28:27", "end_timestamp": "00:30:09", "podcast_index": 62, "episode_name": "EP 62: Chase White | Contract Creatives in 2021 | Chase White Photography", "slug": "ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "guest_name": "Chase White", "guest_title": "Creative Director, Chase White Photography", "categories": [], "short_description": "How clients and contractors can work best together to produce meaningful work.", "podcast_length": "44:84"}, {"id": "d11bd91a-fe3d-4ba3-9c4b-64ee07aca463", "episode_id": "6c349e21-fb5e-4e13-83d4-459a9ed8ae26", "cms_item_id": "68225dfc7bb476527f8c4867", "chunk_index": 16, "content": "Chase White (00:30:28): Totally. My response to that would be that I think you're going to get a certain level of creative intimacy that comes from hiring a single person who's going to own that part of your project with you. Things move quicker. It's not like every email has to go through 20 people and then they have to deliberate how they're going to respond and all kinds of stuff. Like one person with a good creative, you can just shoot 'em a text and be like, Hey, what do you think about this? I think collaboratively. But then there's this sort of gene se quo when you get somebody who really matches up with your brand well and they're just kind of this really powerful lean extension from you, there's a really nice sort of intimacy that shows in the creative. And I think that's what a lot of we're looking for is this authenticity and this intimacy, these really understanding these minute details and how they transpire for the business. So there is something there that I think a small lean person can achieve that an agency is just too big and slow for.\n\nCole Heilborn (00:31:43): Yeah, yeah. Interesting. And not to go down the rabbit hole of contractor versus agency.\n\nChase White (00:31:50): Cool. Let's go down the rabbit hole, man. We're here for it.\n\nCole Heilborn (00:31:55): Fair enough. Yeah. I'm just thinking\n\nChase White (00:32:01): I have to tread lightly here too. My wife runs a creative agency based out of Vancouver and she's totally going to listen to this.\n\nCole Heilborn (00:32:10): Yeah, and I guess all of this just kind of, there's no one size fits all. I feel like in some instances the agency is better. In some instances the contract creative is better. If you could distill down when is the agency better suited, when is the contract creative better suited? What are those differences? Why bring in one versus the other?", "token_estimate": 466, "speakers": ["Chase White", "Cole Heilborn"], "start_timestamp": "00:30:28", "end_timestamp": "00:32:10", "podcast_index": 62, "episode_name": "EP 62: Chase White | Contract Creatives in 2021 | Chase White Photography", "slug": "ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "guest_name": "Chase White", "guest_title": "Creative Director, Chase White Photography", "categories": [], "short_description": "How clients and contractors can work best together to produce meaningful work.", "podcast_length": "44:84"}, {"id": "eee9b5f5-7d9d-4399-bfb7-98a14bcf1e10", "episode_id": "6c349e21-fb5e-4e13-83d4-459a9ed8ae26", "cms_item_id": "68225dfc7bb476527f8c4867", "chunk_index": 17, "content": "Chase White (00:32:34): Totally candidly, and I am truly approaching this without how it's going to affect me or whatever, answering that truthfully, the reality is a brand should employ an agency when there's a really large amount of work to be done and it has to be done properly and it has to be done on time. There is no flexibility. If you're talking about a big blockbuster brand, just pick any one brand. If you're looking at a Lululemon for example, a sort of a big athletic kind of company or something like that, I think if I were that person, I would not hire an individual contract creative to just go run this. You have huge, probably quarterly campaigns that are going out that the amount of revenue tied to those campaigns is hard to comprehend and things have to be done and they have to be done on time. You have thousands and thousands of employees dependent on this. That's a situation where I'm like, you need the safety net of a huge team working on this and you should pay for that.\n\nCole Heilborn (00:33:57): And on the flip side,\n\nChase White (00:34:01): On the side, I think brands that are more niche, I think brands that have more flexibility in their timing of the deliverables. If this person doesn't have a dedicated producer, this person doesn't have a dedicated assistant, this person doesn't have all this stuff, the factors have to line up pretty well for a one man show to really make sure they nail it quickly on time, all this kind of things. So I think that typically smaller companies that are going to benefit from the financial flexibility of using somebody who can operate on leaner terms and somebody who has more flexibility with their timing, with their product, with their campaigns, things like that. That said, I work with plenty of very large brand names in the outdoor industry and we make it work just fine, but it's not typically not like million dollar campaigns that should go to a big agency.", "token_estimate": 487, "speakers": ["Chase White", "Cole Heilborn"], "start_timestamp": "00:32:34", "end_timestamp": "00:34:01", "podcast_index": 62, "episode_name": "EP 62: Chase White | Contract Creatives in 2021 | Chase White Photography", "slug": "ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "guest_name": "Chase White", "guest_title": "Creative Director, Chase White Photography", "categories": [], "short_description": "How clients and contractors can work best together to produce meaningful work.", "podcast_length": "44:84"}, {"id": "0fee11a7-1978-4a21-8ee4-73d00d132bc5", "episode_id": "6c349e21-fb5e-4e13-83d4-459a9ed8ae26", "cms_item_id": "68225dfc7bb476527f8c4867", "chunk_index": 18, "content": "Cole Heilborn (00:35:12): So then why go with the contract creative if the agency offers security results on time, on budget, potentially, why go with the contract creative? Do you get an extra creative flare or a little extra jazz that you can't replicate at an agency?\n\nChase White (00:35:39): I mean, getting right down to the bones of it, you're going to save so much money. What small brand can afford big agency rates? Probably not. And here's the other thing that I'll say is that it's not like, oh, you can do one campaign a year as a brand in 2021 and then you're good for the year. This is the content age. You need to be just constantly putting things out. You need to be constantly staying relevant and staying top of mind with new and prospective customers or users. And so I think if you develop a strong relationship, I have relationships where I'm on retainer with brands that I personally love and I'm out there developing content for them monthly. And that's a situation where if that brand is going to go try to get any kind of comparable relationship with an agency, the proposal is just going to get laughed out of the room. There's no way that they're going to be able to make that work with their team of 30 or whatever.\n\nCole Heilborn (00:36:50): So we've been kind of talking about this in two extremes. We've got on one hand, Wyden Kennedy. On the other hand, we have one solo person. I feel like especially in 2021, your wife's shop sounds like a pretty good example where there's a whole bunch of middle ground shops that are popping up. What's your take on that and the benefits with the small but not individual team?", "token_estimate": 412, "speakers": ["Cole Heilborn", "Chase White"], "start_timestamp": "00:35:12", "end_timestamp": "00:36:50", "podcast_index": 62, "episode_name": "EP 62: Chase White | Contract Creatives in 2021 | Chase White Photography", "slug": "ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "guest_name": "Chase White", "guest_title": "Creative Director, Chase White Photography", "categories": [], "short_description": "How clients and contractors can work best together to produce meaningful work.", "podcast_length": "44:84"}, {"id": "91b18786-a746-4d89-a69b-ccd683d9dc42", "episode_id": "6c349e21-fb5e-4e13-83d4-459a9ed8ae26", "cms_item_id": "68225dfc7bb476527f8c4867", "chunk_index": 19, "content": "Chase White (00:37:23): I think there's a lot of truth to that where there are situations that are perfectly appropriate for a small agency. I think that they can do things really well, and I think a lot of those agencies are the ones that I tend to work with quite frequently. They don't have a photographer on staff, but they have a producer, they have a strategy lead. They probably have some copywriters on staff, they have a designer, they have a cd, but they'll bring in a more specialized skill that may fit the project. So having worked with a lot of brands, a lot of those agencies and continuing to, I think that's a super viable option that a lot of brands should also consider. And that said, I think that you can get similar results with one contract creative that has a strong network. I can bring in a producer, I can bring in an art director, I can bring in other people that I need. I can bring in a second shooter or anything like that. So I think you're right to point out that we have been dealing in sort of polar extremes and it's not a one size fits all and there are middle ground that work really well for a lot of awesome outdoor brands.\n\nCole Heilborn (00:38:51): So okay, switching gears a little bit. When a marketing manager is looking to work with a creative, what are things that they should look for to make the relationship as successful as possible? You've kind of talked about having the creative quality, the business sense, the communication skills, but I guess what are the expectations and what should they go into the relationship looking for to make it successful", "token_estimate": 402, "speakers": ["Chase White", "Cole Heilborn"], "start_timestamp": "00:37:23", "end_timestamp": "00:38:51", "podcast_index": 62, "episode_name": "EP 62: Chase White | Contract Creatives in 2021 | Chase White Photography", "slug": "ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "guest_name": "Chase White", "guest_title": "Creative Director, Chase White Photography", "categories": [], "short_description": "How clients and contractors can work best together to produce meaningful work.", "podcast_length": "44:84"}, {"id": "861eac37-98b4-444f-8e70-fa59afa19f4a", "episode_id": "6c349e21-fb5e-4e13-83d4-459a9ed8ae26", "cms_item_id": "68225dfc7bb476527f8c4867", "chunk_index": 20, "content": "Chase White (00:39:24): Starting at the top of that process? Cole, I think that a lot of brands underestimate the amount of time that goes into research, onboarding, presenting. A lot of the strategy work is done for free upfront, and a lot of that goes into something like a proposal, for example. And so I would personally like to see a lot of brands in 2021 appreciate the proposal process. If you're shopping out a project to three or four different people or agencies or whatever, they're putting a lot of time into that. And I think it's all too often that whether it's me, other people like friends that I work with or agencies that I know of pitching with a request for proposal or something and they're just like, cool, thanks, bye. And it's like, whoa, a lot of work went into that. You should be a good human and embrace that and not just be like, yep, sorry, we're going to the cheapest bidder or whatever. (00:40:37): After someone puts a lot of love and care and something like that. But then moving down into the process of working with somebody with, I just think if you are trusting and you give much, you will receive much. I think that a lot of brands, unfortunately, they're trying to stretch their dollar, they're trying to stretch their dollar really far. That's not unfortunate, that's understandable. I really do get that. You have a lean budget and you're trying to get as much done with as little as possible, but what that can often transpire into is a brand approaching a near abusive relationship with the creative where it's like, look, not everything is an opportunity to save money. And oftentimes when you give a little bit more, that person is going to feel emboldened to really want to overdeliver. Whereas if somebody is just kind of nickel and dimming and nickel and diming all the time, it's like, I can't wait to get out of this relationship with you. (00:41:57): And I think that there's things that you can do in that regard that you're just being a good human and overdelivering. Think of your brand as a human, be a good human and overdeliver and that person will want to over deliver for you and they want to make you look really good. But that said, there's other things I think you could do. You can support their sort of causes and projects they have. You can help lift them up. You can be a good steward of giving credit where credit is due even though you're not contractually obligated to. There's a lot of things you can do like that, but I think if you just kind of come back to the mindset of, Hey, I want my brand to be perceived as a good human, what can I do in that light and how can I give more than I expect to receive with this relationship?", "token_estimate": 676, "speakers": ["Chase White"], "start_timestamp": "00:39:24", "end_timestamp": "00:39:24", "podcast_index": 62, "episode_name": "EP 62: Chase White | Contract Creatives in 2021 | Chase White Photography", "slug": "ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "guest_name": "Chase White", "guest_title": "Creative Director, Chase White Photography", "categories": [], "short_description": "How clients and contractors can work best together to produce meaningful work.", "podcast_length": "44:84"}, {"id": "3e593db0-8640-45fb-8e0c-f5f568dd0312", "episode_id": "6c349e21-fb5e-4e13-83d4-459a9ed8ae26", "cms_item_id": "68225dfc7bb476527f8c4867", "chunk_index": 21, "content": "Cole Heilborn (00:42:54): The proposal comment is really interesting and I want to take us back there to dive a little deeper. So you mentioned that sometimes contractors or agencies submit a proposal, client just takes it, puts it on the shelf and is like, cool, we'll get back to you or we skip to the budget sheet and we're going to go with the cheapest option. I guess a couple of questions surrounding that. One again, when it comes to responsibility is that the contractor's responsibility to say no know when to put together a proposal and when not to put together a proposal. And on the flip side for the client, when is it right for the client to ask for a proposal? Experienced clients just asking for proposals, we don't really know what we want, we're just hoping to see what we get. And that's generally when I say, okay, no, tell me. Let's figure out what you want and then we will move forward with the proposal. So I guess coming back to that responsibility, whose is it? And I guess how do you approach that?\n\nChase White (00:44:00): I think that's a two part thing where I think the second scenario you described is the right way to handle it. As the contractor, I don't think you should be brainstorming by proposal. What a nightmare process that must be.\n\nCole Heilborn (00:44:23): I love that phrase. That's really good.", "token_estimate": 336, "speakers": ["Cole Heilborn", "Chase White"], "start_timestamp": "00:42:54", "end_timestamp": "00:44:23", "podcast_index": 62, "episode_name": "EP 62: Chase White | Contract Creatives in 2021 | Chase White Photography", "slug": "ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "guest_name": "Chase White", "guest_title": "Creative Director, Chase White Photography", "categories": [], "short_description": "How clients and contractors can work best together to produce meaningful work.", "podcast_length": "44:84"}, {"id": "1c2269c3-3fdc-437c-bb67-f53284f2c7e2", "episode_id": "6c349e21-fb5e-4e13-83d4-459a9ed8ae26", "cms_item_id": "68225dfc7bb476527f8c4867", "chunk_index": 22, "content": "Chase White (00:44:27): It gives me chills. That's horrible. I might have nightmares about that. No, I think the bigger piece of responsibility is on the brand. Don't come to a creative that you respect that whose time is very limited and valuable without real intent to consider this shame on the person who's asking for proposals as a way to sort of farm ideas. That's just terrible. But also, did you think this was going to be free when you hit that budget sheet and you're like, wow. But that said, I think that there's a lot of room for once you hit that, for the people who do get to that point, which for all types of whether you're a copywriter or a videographer or whatever, there always is going to be that sticker shock factor because you are a good creative doing good work and you should price it accordingly. (00:45:34): And a lot of brands just want to see a best case scenario going into this. Then they hit that and they're like, oh wow, I thought this was going to be much cheaper. And so they just go tightlipped and disappear. Whereas there's a much better way to handle that and you can have a back and forth. The reality is most people are willing to work with you on budgets, on timelines, on deliverables, on all kinds of things to make it work. If you've got somebody into that proposal process, like rest assured they want to work with you probably. And so I think continuing that conversation and not going silent on them is a way to respect that person and the work that they've put into it up to that point,\n\nCole Heilborn (00:46:19): How many ideas do you put into your proposal free of charge? Something I've questioned a lot and there's some books that I've read around the topic of giving away your ideas without actually selling them as a contract creative. How do you protect yourself by giving away your ideas? How many ideas do you give away? Do you charge for those initial ideas? There's a book that I'm thinking of currently, it's called The Win Without Pitching Manifesto. It's written by Blair Ends and it talks all about don't sell your ideas, sell how you're going to come up with the ideas, but don't give me your ideas.", "token_estimate": 542, "speakers": ["Chase White", "Cole Heilborn"], "start_timestamp": "00:44:27", "end_timestamp": "00:46:19", "podcast_index": 62, "episode_name": "EP 62: Chase White | Contract Creatives in 2021 | Chase White Photography", "slug": "ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "guest_name": "Chase White", "guest_title": "Creative Director, Chase White Photography", "categories": [], "short_description": "How clients and contractors can work best together to produce meaningful work.", "podcast_length": "44:84"}, {"id": "65809884-83c7-44c8-84ae-6a07113d3929", "episode_id": "6c349e21-fb5e-4e13-83d4-459a9ed8ae26", "cms_item_id": "68225dfc7bb476527f8c4867", "chunk_index": 23, "content": "Chase White (00:47:02): That's super interesting. And I tend to lean in the opposite direction where I like to give more and demonstrate I was raised in my agency experience, I was raised as give something away for free. That's the best way to sell something and that may be wrong and that may not work right for everybody. And Lord knows I've been ghosted on before and it's like they're probably out executing my ideas. But that's part of the business and I think when you offer trust for somebody, a good person that you want to work with will respect that and give trust back to you, and those are the people that I want to work with.\n\nCole Heilborn (00:47:55): You feel by giving trust, that's then reciprocated and hopefully sets the stage for the relationship moving forwards to be a really positive one.\n\nChase White (00:48:04): And if you're the type that is going to try to utilize any of that in any kind of unsavory way of try to take that and run with it or use it with someone else who's cheaper or whatever it is, you're the type of person I don't want to work with and thanks for calling yourself out for me in advance rather than once we get into this relationship.\n\nCole Heilborn (00:48:29): And I think I feels like that's what this conversation kind of boils down to is that level of trust and it seems really obvious, but I feel like that's kind of what we've hit on is that's the root of a successful relationship", "token_estimate": 359, "speakers": ["Chase White", "Cole Heilborn"], "start_timestamp": "00:47:02", "end_timestamp": "00:48:29", "podcast_index": 62, "episode_name": "EP 62: Chase White | Contract Creatives in 2021 | Chase White Photography", "slug": "ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "guest_name": "Chase White", "guest_title": "Creative Director, Chase White Photography", "categories": [], "short_description": "How clients and contractors can work best together to produce meaningful work.", "podcast_length": "44:84"}, {"id": "94bd6592-1b9e-45b3-9412-74f86f61dde5", "episode_id": "6c349e21-fb5e-4e13-83d4-459a9ed8ae26", "cms_item_id": "68225dfc7bb476527f8c4867", "chunk_index": 24, "content": "Chase White (00:48:45): A hundred percent. I mean I think whether that's a relationship you have personally with a friend or a partner or that's a relationship that you have with a coworker or you have with an agency or a brand that you're working with, these truths that we kind of hold for ourselves, they don't disappear because working together you should still be thoughtful and caring and giving in the work that you're doing. And I think when you couple that with a real high level of creative proficiency and integrity and passion for the project that you're working on, that's when these things really start to sing and that's when you build long-term relationships with people that are working for your brand, creating super top level creative that you never could have got with a big dollar agency. Agency retainers are expensive. When you can put all these pieces of this relationship into the recipe where you have trust on both sides and you want to keep working together, that's a great relationship for everybody and one that I would encourage people to try to seek out.\n\nCole Heilborn (00:50:03): So for yourself, let's say you've got a new client in the pipeline you're chatting with and it seems like a good relationship to pursue. I guess, what are things that you think of that you could share with the audience in terms of how you as a contractor can continue to do better work? Are there things that you look for or that you need from the client in order to continue your own creative growth? Because I feel like that's one of the reasons why a lot of us get into the field is because we want to get better creatively. And sometimes you get into it and you find those clients who just let you run with it and you knock it out of the park and it's awesome. Other times though, there's those relationships where you feel like you're stifled and it's just not working for people who are trying to figure out how do I grow as a creative while still doing client work, what are the pieces that they need in order to make that work?", "token_estimate": 513, "speakers": ["Chase White", "Cole Heilborn"], "start_timestamp": "00:48:45", "end_timestamp": "00:50:03", "podcast_index": 62, "episode_name": "EP 62: Chase White | Contract Creatives in 2021 | Chase White Photography", "slug": "ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "guest_name": "Chase White", "guest_title": "Creative Director, Chase White Photography", "categories": [], "short_description": "How clients and contractors can work best together to produce meaningful work.", "podcast_length": "44:84"}, {"id": "85a0a9bf-5b67-4d02-8185-6eed6a0f5b6a", "episode_id": "6c349e21-fb5e-4e13-83d4-459a9ed8ae26", "cms_item_id": "68225dfc7bb476527f8c4867", "chunk_index": 25, "content": "Chase White (00:51:01): Man, that's a good one. I think that there's a lot to be said for honing in to sort of take a storytelling approach. And I know that word is thrown around a lot, but as somebody who is an editorial photographer that singularly has benefited my brand work better than many, many other things that I've worked on, and applying that storytelling lens to brand work is something I think is often lost. And I think that, well, you can get as technically proficient as you want. Anyone can YouTube how to learn every single piece of the menu in a Sony a seven R or whatever. I think jumping back and taking a more sort of 30,000 foot level at your work is like, how can I really build a story and how can I really apply that to my work? I think that's something that will help elevate the whole ecosystem of outdoor brand creative. From the contractor perspective specifically, I think that's unfortunately lost a lot of the time.\n\nCole Heilborn (00:52:28): Well expand on that. What do you mean it's lost? Do you feel like there's something that could be done better?\n\nChase White (00:52:33): I do. I would like to see more of an editorial approach taken to a lot of product work. The outdoor marketing space is, I don't know, what would you say, 90% product, 10% service, right? There's a lot outdoor product marketing and I think too often people are just trying to sort of get right to it, and I don't know if this is too much, but just skipping the foreplay, take the time to really build the story. And I think the end result is that there's a lot more empathy from the person you're marketing to who can be along for a journey. Don't just get into how can we market this thing? It's just get rid of that, take a bit of an editorial approach and I think that the story will have more profound results.\n\nCole Heilborn (00:53:39): But are we not already seeing that? I feel, I feel like that's pretty prevalent in the outdoor space. Maybe that's not true or maybe that we just see it differently.", "token_estimate": 505, "speakers": ["Chase White", "Cole Heilborn"], "start_timestamp": "00:51:01", "end_timestamp": "00:53:39", "podcast_index": 62, "episode_name": "EP 62: Chase White | Contract Creatives in 2021 | Chase White Photography", "slug": "ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "guest_name": "Chase White", "guest_title": "Creative Director, Chase White Photography", "categories": [], "short_description": "How clients and contractors can work best together to produce meaningful work.", "podcast_length": "44:84"}, {"id": "2d91be69-01cd-4cb5-ba37-fb0ade1f5d70", "episode_id": "6c349e21-fb5e-4e13-83d4-459a9ed8ae26", "cms_item_id": "68225dfc7bb476527f8c4867", "chunk_index": 26, "content": "Chase White (00:53:49): It's possible. I think I see from clients and from other brand work that I see out, I feel like we're not taking the time to tell a story that isn't about necessarily the product. It always comes back to the product. And I feel like as a consumer, I'm being advertised to. And that's something that I think that is really helpful for creatives to understand is how can you tell a powerful story here? Not how can you create assets to market this product.\n\nCole Heilborn (00:54:28): Okay. I'm tracking. I guess I continue to clarify because maybe not everyone does it, but I guess everyone looks at those types, that type of branded content or that type of storytelling and they're like, we want to do this, but then there seems to be a disconnect between brands that actually do it and brands that say they want to do it. Why is that?\n\nChase White (00:55:00): Ultimately? I think it's because you're right, everybody says they want to do it right? There are some that do it and there are some that don't do it. And I think it is cool that the intention is right, but it's just because I personally think it's just because people can't separate themselves from the end result. And I think there are brands that do that really well where it ends up being that I don't feel like I'm being marketed to. And I think that's just one of the most powerful things that a brand can embrace in the outdoor space today is how can you make your consumers feel like they're not being marketed to? And I think that that'll be embraced and show powerful results.\n\nCole Heilborn (00:55:55): But why is that something that brands should be considering? I get it from the creative perspective, you want to make pretty editorial content and you don't want to have to sell a product, but why? From the brand side, I am assuming a simple brand, they just need to sell product, they need to make their quarterly goals. Why does it matter how they sell their product?", "token_estimate": 492, "speakers": ["Chase White", "Cole Heilborn"], "start_timestamp": "00:53:49", "end_timestamp": "00:55:55", "podcast_index": 62, "episode_name": "EP 62: Chase White | Contract Creatives in 2021 | Chase White Photography", "slug": "ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "guest_name": "Chase White", "guest_title": "Creative Director, Chase White Photography", "categories": [], "short_description": "How clients and contractors can work best together to produce meaningful work.", "podcast_length": "44:84"}, {"id": "9dd9d952-0d92-46f1-ae04-f62b43416c36", "episode_id": "6c349e21-fb5e-4e13-83d4-459a9ed8ae26", "cms_item_id": "68225dfc7bb476527f8c4867", "chunk_index": 27, "content": "Chase White (00:56:21): Because as a brand, you should not thinking about how you can sell your product, you should be thinking about how you can inspire people. And if you inspire somebody like me personally, if you inspire me to want to go get out on the river or to go touring with my friends, I can't help but think about your product. I can't help but want to attach myself to that. I can't help but think that's the type of person I want to be associated with. That's the kind of person for a creative inspiration is it's everything. It's the start of everything. And if you can as a brand, you can inspire me that's like, you've gotten through my skin, you're in my heart now. I want you and I to be a part of each other and I'm now even willing to extend your brand as an extension of my own personal brand, which I think is, it's a powerful way to approach marketing.\n\nCole Heilborn (00:57:21): Yeah, no, that's well said. I don't disagree with you. I just want to hear it put into words.\n\nChase White (00:57:29): No, ultimately I'm just like, man, stop selling and start inspiring. And I think that you'll ultimately, it's just going to show in the bottom line, it's like it seems counterintuitive, but that's how you kind of sell with emotion.\n\nCole Heilborn (00:57:44): Coming back to I guess how you work with your clients when let's say a client comes to you and really simple, they say they want to make product, take product photos, you say, no, let's consider this other option. How much do you push the client versus how much do you expect them to come to you with these ideas? How much of a consultant role do you play versus just a photographer with your business?", "token_estimate": 421, "speakers": ["Chase White", "Cole Heilborn"], "start_timestamp": "00:56:21", "end_timestamp": "00:57:44", "podcast_index": 62, "episode_name": "EP 62: Chase White | Contract Creatives in 2021 | Chase White Photography", "slug": "ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "guest_name": "Chase White", "guest_title": "Creative Director, Chase White Photography", "categories": [], "short_description": "How clients and contractors can work best together to produce meaningful work.", "podcast_length": "44:84"}, {"id": "3087889a-3d63-4709-acc3-24bb2a9ee588", "episode_id": "6c349e21-fb5e-4e13-83d4-459a9ed8ae26", "cms_item_id": "68225dfc7bb476527f8c4867", "chunk_index": 28, "content": "Chase White (00:58:12): Yeah, no, it is a really good dynamic to understand. I personally approach these things as a consultant first, and I really find myself much more invested when I can support in ways that really blur the line of creative and strategy. And I think that's the responsibility of the contractor to be honest with you, because you're talking about how you're going to execute these things and I think that the brand can say, here's what we want to get done, but you coming to this specialist for a reason and I think you should empower them to bring this to life how they want. I think it's ultimately a collaborative process, but if you remove all of that trust from the creative that you're hiring, they're just a button pusher at that point. And I think that you're ultimately hurting yourself by doing that. So I think a really good contractor will insist and remind them that, Hey, you're bringing me into this because you trust me. And if you're doing that, I think we should do it in a way that follows my process, my process. I've honed in over X amount of time and it works really well and that's why you're here. If we break that process, then I can't guarantee the results and I don't think that it's going to be as strong of any result. So it's collaborative, but ultimately I would put the onus on the contractor in that situation.\n\nCole Heilborn (00:59:59): Okay, interesting. So we're kind of running towards the end of our time here, but if you had to give, I dunno again, the marketing managers and the contractors who are listening, just some final thoughts around any of the things we've talked about because we've talked about a lot, but just some key takeaways, I dunno, sum it all up for us. What's the best way to work together?\n\nChase White (01:00:28): What's the best way to work together?\n\nCole Heilborn (01:00:31): Sure", "token_estimate": 466, "speakers": ["Chase White", "Cole Heilborn"], "start_timestamp": "00:58:12", "end_timestamp": "01:00:31", "podcast_index": 62, "episode_name": "EP 62: Chase White | Contract Creatives in 2021 | Chase White Photography", "slug": "ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "guest_name": "Chase White", "guest_title": "Creative Director, Chase White Photography", "categories": [], "short_description": "How clients and contractors can work best together to produce meaningful work.", "podcast_length": "44:84"}, {"id": "6c2022fa-7e0b-4dc0-94ab-b1f1d2eb96b3", "episode_id": "6c349e21-fb5e-4e13-83d4-459a9ed8ae26", "cms_item_id": "68225dfc7bb476527f8c4867", "chunk_index": 29, "content": "Chase White (01:00:35): Man, I think the best way to work together is to start from this place of trust and foster that authenticity through your work together. I think yeah, if you give a lot, you get a lot and I think that's a big part of the relationship of how you're going to work together. But whether you are a creative or you are a marketing manager working in outdoor product marketing, I think you have to be passionate about what you're doing. And I think you have to be passionate about not necessarily just your product. I think it's like over the past four or five years, the landscape of how we talk about things has changed so much through action, through media. I think when brands that stand up for something that they believe in, I think that ends up being something that people can emotionally attach themselves to. And I think how you can get to that point together is something that is really powerful. And I would encourage a lot of brands to employ in their upcoming marketing calendars. Try to be selfless, try to treat better people better than they treat you. And I would encourage you to sort of as a brand, envision yourself as a human. And it makes it a little bit easier to ask yourself like, Hey, am I being a good human right now? Am I standing up for things I believe in? Am I inspiring people? (01:02:24): Am I going out and being generous and caring with my time? And ultimately, if you do those things, like assuming that you are going to be working with people that are technically and creatively proficient and have powerful ideas on their own, I think it's going to come back and you'll see dividends in your bottom line and your brand perception, which is ultimately what I think we're all kind of after in the space.\n\nCole Heilborn (01:02:54): Yeah, well said. If folks want to follow along with you, if they want to find your latest film, any of your photography, where can people go to connect?", "token_estimate": 485, "speakers": ["Chase White", "Cole Heilborn"], "start_timestamp": "01:00:35", "end_timestamp": "01:02:54", "podcast_index": 62, "episode_name": "EP 62: Chase White | Contract Creatives in 2021 | Chase White Photography", "slug": "ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "guest_name": "Chase White", "guest_title": "Creative Director, Chase White Photography", "categories": [], "short_description": "How clients and contractors can work best together to produce meaningful work.", "podcast_length": "44:84"}, {"id": "9563f5a9-a10b-42ce-8078-dbe9db5c8f95", "episode_id": "6c349e21-fb5e-4e13-83d4-459a9ed8ae26", "cms_item_id": "68225dfc7bb476527f8c4867", "chunk_index": 30, "content": "Chase White (01:03:05): Yeah, so you can follow me on Instagram, it's anus, or you can just search Chase White. You can find a lot of my work on my website@chasewhite.com. And my film is coming out and it actually goes live today, March 10th, but will be available online through a number of different film festivals throughout the rest of 2021. It's called Leap Here and it's a story about fish and people and it's a really fun flick to check out.\n\nCole Heilborn (01:03:39): Awesome. Well Chase, yeah, thanks for sitting in the hot seat. This is a tough, I don't know, a tough conversation. There's no one answer, but I appreciate you kind of sharing your thoughts on it.\n\nChase White (01:03:53): No, dude, same. I appreciate it and it's one that I'm excited to have with you because I know you get it. I know you're kind of on a few different sides of the gun as well here. And so I know you've made a safe space for me, which I appreciate, but I'm just a huge fan of the podcast myself, and so it's a real honor and a pleasure as a longtime listener to be on it.\n\nCole Heilborn (01:04:17): Well, that means a lot. I really do appreciate that. We're only a year old, actually, our 52nd episode is coming up here, so yeah, long time. I guess we haven't been around that long, but who knows where we'll be in five years.\n\nChase White (01:04:33): There's just so much good content, man. Honestly, I would be hard pressed to find any other marketing podcasts that kind of really does resonate. You're skipping through a lot of the bs, you're bringing in really rad guests and on my sort of evening trail runs, it's a necessity.", "token_estimate": 407, "speakers": ["Chase White", "Cole Heilborn"], "start_timestamp": "01:03:05", "end_timestamp": "01:04:33", "podcast_index": 62, "episode_name": "EP 62: Chase White | Contract Creatives in 2021 | Chase White Photography", "slug": "ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "guest_name": "Chase White", "guest_title": "Creative Director, Chase White Photography", "categories": [], "short_description": "How clients and contractors can work best together to produce meaningful work.", "podcast_length": "44:84"}, {"id": "017a0248-ca37-4824-8ad6-0691342265a1", "episode_id": "6c349e21-fb5e-4e13-83d4-459a9ed8ae26", "cms_item_id": "68225dfc7bb476527f8c4867", "chunk_index": 31, "content": "Cole Heilborn (01:04:53): Well, maybe we can revisit this conversation in a few months or a year from now and pick your brain again on how contractors and the clients can work better together. I'd encourage anyone who has thoughts or questions or just has had success with these types of relationships, I dunno, reach out to us. Let us know. I think we're always trying to learn and pay it forwards, pass on the knowledge that everyone has kind of gathered. And again, that's kind of the goal of this podcast. And yeah, if Chase is cool with it, feel free to hit him up if you have any more questions around this stuff.\n\nChase White (01:05:30): Totally, man. I appreciate it. Thanks Cole.\n\nCole Heilborn (01:05:32): Yeah, thank you Chase, and have a good rest of your day.\n\nChase White (01:05:35): Alright, thanks brother.\n\nCole Heilborn (01:05:38): Thank you for listening to this episode of the Backcountry Marketing Podcast. If you enjoyed today's episode or learned something new, please consider leaving us a review on Apple or sharing this with a friend.", "token_estimate": 265, "speakers": ["Cole Heilborn", "Chase White"], "start_timestamp": "01:04:53", "end_timestamp": "01:05:38", "podcast_index": 62, "episode_name": "EP 62: Chase White | Contract Creatives in 2021 | Chase White Photography", "slug": "ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "web_url": "https://www.portsidepro.com/podcast-feed/ep-62-chase-white-contract-creatives-in-2021-chase-white-photography", "guest_name": "Chase White", "guest_title": "Creative Director, Chase White Photography", "categories": [], "short_description": "How clients and contractors can work best together to produce meaningful work.", "podcast_length": "44:84"}, {"id": "653ca5de-ca59-479d-8ef1-860ae533ea90", "episode_id": "3e7889c2-9d6c-435a-a418-c44adcef7ff3", "cms_item_id": "68225dfc7bb476527f8c4869", "chunk_index": 0, "content": "Carie Behe (00:03): How do these brands really start identifying how they can talk to people that might not feel like they belong? And I think my personal experience, it resonates so much with that because I didn't feel like I belonged. Even sometimes to this day is like I'm not the fastest in what I do. I've experienced with, I think with the gear culture of the outdoor industry, you have to have the lightest, the fastest, the next greatest thing. Oftentimes a lot of garments haven't fit me.\n\nCole Heilborn (00:33): Welcome to the Backcountry Marketing Podcast. My name is Cole Hallborn and I'll be your host today. This podcast dives deep with leaders of the outdoor marketing industry as they discuss the gritty details of their work, personal challenges and latest adventures, whether you're standing in the lift line, shuttling to fresh loam or cracking a local beer. I hope you enjoyed today's episode. This is the Back Country Marketing Podcast. This episode is produced by Portside Productions, an outdoor, commercial and film production company based in the Pacific Northwest. Welcome to the Backcountry Marketing Podcast. My name is Cole Heur. Today I'm sitting down with Carrie Behi, the GDM Marketing manager at Cotopaxi. Carrie, how are you?\n\nCarie Behe (01:14): I'm doing good. How are you doing?\n\nCole Heilborn (01:16): Fantastic. Thanks for joining us today. Where are you calling in from?\n\nCarie Behe (01:19): I'm calling in from Portland, Oregon. This has been my home in the northwest, most of my adult life.\n\nCole Heilborn (01:25): Beautiful. Well, again, super excited to have you on the show today and to dive into our topic, I'd love to first get a little bit of background on Cotopaxi and your role as a go-to-market marketing manager. Could you break that down for us?", "token_estimate": 450, "speakers": ["Carie Behe", "Cole Heilborn"], "start_timestamp": "00:03", "end_timestamp": "01:25", "podcast_index": 62, "episode_name": "EP 63: Carie Behe | Inclusivity and Marketing | Cotopaxi", "slug": "ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "web_url": "https://www.portsidepro.com/podcast-feed/ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "guest_name": "Carie Behe", "guest_title": "GTM Marketing Manager, Cotopaxi", "categories": [], "short_description": "How can brands speak to people who might not feel included?", "podcast_length": "44:85"}, {"id": "33151007-5813-4168-8c3a-f940f870b4d9", "episode_id": "3e7889c2-9d6c-435a-a418-c44adcef7ff3", "cms_item_id": "68225dfc7bb476527f8c4869", "chunk_index": 1, "content": "Carie Behe (01:40): Yeah, sure. So I started with Cotopaxi in the fall. I've been with them for about almost six months now, which is wild to think how fast it's gone so far. But the go-to-market marketing manager is a new role for Co Epoxy. It's a relatively small marketing team. And so this is a new position that really essentially is trying to build process from start to finish on go to market. And really what that means is from ideation of product and concept to all the way to the product sitting on the store shelf, I'm responsible for developing the process, identifying the stage gates and milestones, writing the campaign briefs, and then working really closely with our stakeholders across all different departments on the team, sales, product, merchandising, our design team, our creative team is probably the biggest team I work with. And then seeing that all the way through to execution on co epoxy.com in our retail stores and then with wholesale partners.\n\nCole Heilborn (02:42): And it sounds like that role is pretty fresh. It it's an expanding role that's been added as you guys have been growing.\n\nCarie Behe (02:49): Yeah, it's a brand new role and I have been saying this phrase with the team, they're probably sick of me saying it as like I'm flying the plane while building it. Plane is up in the air. There's not really a wing on it. I'm not sure if the tires are on it right now, but we're flying it in real time and I'm figuring it out. So I'm really taking 2021 as a Guinea pig type of year to develop processes as I've learned from past roles and test and learn and see how it will work in terms of all the campaigns that we're launching, the collaborations that this brand launches. We do a lot of collaborations with other partners. And so feeling how we can do all of these things at once and work on things simultaneously, understanding that there is a much longer calendar to do campaigns with.\n\nCole Heilborn (03:39): Yeah. And I guess for folks maybe who aren't familiar, could you give us a little bit of background on Cotopaxi itself?", "token_estimate": 519, "speakers": ["Carie Behe", "Cole Heilborn"], "start_timestamp": "01:40", "end_timestamp": "03:39", "podcast_index": 62, "episode_name": "EP 63: Carie Behe | Inclusivity and Marketing | Cotopaxi", "slug": "ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "web_url": "https://www.portsidepro.com/podcast-feed/ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "guest_name": "Carie Behe", "guest_title": "GTM Marketing Manager, Cotopaxi", "categories": [], "short_description": "How can brands speak to people who might not feel included?", "podcast_length": "44:85"}, {"id": "2369c792-0003-4a6d-ac5d-7409c4aa7e5f", "episode_id": "3e7889c2-9d6c-435a-a418-c44adcef7ff3", "cms_item_id": "68225dfc7bb476527f8c4869", "chunk_index": 2, "content": "Carie Behe (03:44): Yeah, so Epoxy is an almost 7-year-old brand born, a digitally native brand in the outdoor industry. And it was founded by really incredible entrepreneur named Davis Smith. And his goal with this brand is really to help fight and alleviate poverty and really wanting to develop a brand in the outdoor industry that gives back. And there's so many brands in the industry that give back, but I think what sets Epoxy apart with that is not only is it a certified B corporation, but that it is giving the stake in the ground for Cotopaxi is really to alleviate poverty.\n\nSpeaker 3 (04:24): Whereas\n\nCarie Behe (04:24): So many other brands in the industry, their stake in the ground and giving back is environmentalism. Sustainability is to help get more people outside and protect the places that we're all playing in. But Cotopaxi is a little bit different from that regard, and I think most people that know who Ko Epoxy is recognizes the brand through the Fun Llama logo that we have. We have a llama as a mascot for the brand. And I think in the very early days, there were actually two llamas that the brand owned and Davis and some of the initial founders would take the llamas on campus around different universities in Utah to attract attention and start talking about how the brand was being built. And I would say the other side of what the brand is founded on is trying to find ways to sustainably manufacture and resource all of the materials that we're using. (05:18): Fair Trade's, very important. Everything that we're doing in our factories from how workers are treated, what is being sourced, we give creative control to our factory workers that sew a certain collection of our packs. They're called Del dea. And these packs are all one of a kind, they're sourced from remnant factory scraps. So they are entirely unique. And what's cool is these remnant factory scraps would've otherwise gone to waste. So we're trying to find a second life for things that otherwise would have been put into a landfill. So from a product perspective, the product is very vibrant and bright, fun colors unique and sets itself apart when you see it in the store.", "token_estimate": 545, "speakers": ["Carie Behe", "Speaker 3"], "start_timestamp": "03:44", "end_timestamp": "04:24", "podcast_index": 62, "episode_name": "EP 63: Carie Behe | Inclusivity and Marketing | Cotopaxi", "slug": "ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "web_url": "https://www.portsidepro.com/podcast-feed/ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "guest_name": "Carie Behe", "guest_title": "GTM Marketing Manager, Cotopaxi", "categories": [], "short_description": "How can brands speak to people who might not feel included?", "podcast_length": "44:85"}, {"id": "2472fa13-78af-475c-8fcb-095864a96e7a", "episode_id": "3e7889c2-9d6c-435a-a418-c44adcef7ff3", "cms_item_id": "68225dfc7bb476527f8c4869", "chunk_index": 3, "content": "Cole Heilborn (06:04): Yeah, I think that's a great way to describe it. It's bright, it's poppy. You're like, man, it looks like it came out of the eighties, but it's not nearly as tacky.\n\nCarie Behe (06:13): No. And I think the story behind the jacket is just, it's so inspiring and it's what motivated me to apply for this role and I want to work for a brand that gives back. It's so important to me and I've, I said this in my interview, is just, I don't want to just show up and collect a paycheck. And I've been in the outdoor industry for about 12 years now and really working for a brand that cares holistically about what it's doing and not just the profit that it's making about the people that it employs, it's factory workers, how it is showing up in the world and caring for the environment and the planet. It's just, it's so important and this brand fully embodies it unlike many that I've seen or that I have worked for.\n\nCole Heilborn (06:58): You mentioned that a large part of the mission of Cotopaxi is to help alleviate poverty. In what ways do you do that? What does that look like?", "token_estimate": 276, "speakers": ["Cole Heilborn", "Carie Behe"], "start_timestamp": "06:04", "end_timestamp": "06:58", "podcast_index": 62, "episode_name": "EP 63: Carie Behe | Inclusivity and Marketing | Cotopaxi", "slug": "ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "web_url": "https://www.portsidepro.com/podcast-feed/ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "guest_name": "Carie Behe", "guest_title": "GTM Marketing Manager, Cotopaxi", "categories": [], "short_description": "How can brands speak to people who might not feel included?", "podcast_length": "44:85"}, {"id": "40f88700-e0e3-4068-9798-876f9d28a46e", "episode_id": "3e7889c2-9d6c-435a-a418-c44adcef7ff3", "cms_item_id": "68225dfc7bb476527f8c4869", "chunk_index": 4, "content": "Carie Behe (07:05): Cotopaxi has a foundation that was started officially about a year ago, I believe. And the Cotopaxi Foundation really is how we're giving back in terms of grant donations to nonprofit partners. And Cotopaxi has five nonprofit partners now, longer term grantee partners that we're establishing a relationship with that we will give grant money over a longer period of time, multiple years and wanting to grow and help fund projects that they're working on. So an example of one of our longer term grantee partners is Mercy Corps. They're based in Portland really helping provide relief, especially in the past year with COVID of providing relief in areas in the Americas that were just hit so hard, providing relief in terms of food, shelter support, providing relief in terms of education access. So people, children that weren't able to go to school any longer, finding ways to help them digitally access and continue their education during the pandemic. (08:09): There was a lot of really great local support that Cotopaxi did last year in the Utah community itself in Salt Lake partnering with the Utah Jazz and creating a t-shirt for that. And then at the same time, just giving back to the local community to help support with COVID Reliefs with everything that was happening with COVID last year. And the Pandemic Cotopaxi really, it had its most successful year of giving in the company's history, which was really exciting. And one of the things that our director of Impact has said, and she's quoted Bill Gates saying that 25 years of human development were undone in 25 weeks. I mean just what has happened in the past year because of this pandemic. And I think that's just been such another great component of this brand of why we give back. And this year especially being able to still, despite everything that happened, how businesses were hit hard in a variety of ways for Cotopaxi to have its most successful year of giving to date was really powerful. I mean, over eight, 880 million people were indirectly impacted through all of the giving that we did,", "token_estimate": 523, "speakers": ["Carie Behe"], "start_timestamp": "07:05", "end_timestamp": "07:05", "podcast_index": 62, "episode_name": "EP 63: Carie Behe | Inclusivity and Marketing | Cotopaxi", "slug": "ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "web_url": "https://www.portsidepro.com/podcast-feed/ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "guest_name": "Carie Behe", "guest_title": "GTM Marketing Manager, Cotopaxi", "categories": [], "short_description": "How can brands speak to people who might not feel included?", "podcast_length": "44:85"}, {"id": "fcde3d90-5fa9-40cc-a400-81439021b57b", "episode_id": "3e7889c2-9d6c-435a-a418-c44adcef7ff3", "cms_item_id": "68225dfc7bb476527f8c4869", "chunk_index": 5, "content": "Cole Heilborn (09:21): That 25 years undone in 25 weeks. I don't know. That's phenomenal. And that's unfortunate. I don't feel like you hear that you have to go searching or you have to be someone in that crowd in order to learn that information. That's not something that I feel like most people would know. I mean, I didn't know that until a minute ago.\n\nCarie Behe (09:43): I know. And when she had first said that, and it's something that's been reiterated when we talk about we have meetings of giving and why we're giving and then the plans for 2021 and where our donations will be going, our grants will be going into who it is. Really being mindful of that of this past year really just completely turned everyone's lives upside down. And I think it illustrates the importance of why a brand should give back whatever the stake in the ground is for that brand environmentalism, humanitarian efforts that you should be able to prioritize giving back in some way.\n\nCole Heilborn (10:25): I want to switch gears, not because I don't think this is important, but because we have a lot of other fantastic things to talk about. So you're currently working on a pretty unique collaboration and I think that probably would give us a really good idea of what your role as a go-to-market marketing manager looks like. And as you said, you're kind of building the plane as you're flying it. So could you kind of break breakdown, I guess, what you've been working on and further explain what does your role do?", "token_estimate": 377, "speakers": ["Cole Heilborn", "Carie Behe"], "start_timestamp": "09:21", "end_timestamp": "10:25", "podcast_index": 62, "episode_name": "EP 63: Carie Behe | Inclusivity and Marketing | Cotopaxi", "slug": "ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "web_url": "https://www.portsidepro.com/podcast-feed/ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "guest_name": "Carie Behe", "guest_title": "GTM Marketing Manager, Cotopaxi", "categories": [], "short_description": "How can brands speak to people who might not feel included?", "podcast_length": "44:85"}, {"id": "350e4dc0-de9c-4939-b424-6bf53d4b193a", "episode_id": "3e7889c2-9d6c-435a-a418-c44adcef7ff3", "cms_item_id": "68225dfc7bb476527f8c4869", "chunk_index": 6, "content": "Carie Behe (10:51): Yeah. And with this project specifically should give a good breakdown of it. So this collaboration that we're launching, it's in a few weeks. So a launch on March 30th with Hoka super exciting project. And I think I've said it's one of the biggest projects I've worked on. It's certainly the biggest collaboration I have ever worked on. And so essentially Epoxy and Hoka have gotten together to create some fun product. Hoka is showing up with a pair of trail runners, the Torrent two, and we are showing up with apac, it's called the oc. And really it's just such a fun explosion of colors on both of these products. They're vibrant on the shoes itself. They are two different colors. Each of the shoe, like the right and the left, and then the pack is the Dell DEA pack, like I mentioned earlier. It's one of a kind, very unique and it has Hokas logo on it and the look and feel of the pack and the shoe are similar. (11:51): And so it's just a really product pairing. And we have a really great exclusive retail partner in REI that's bringing this to market. I would say from the campaign launch perspective, and really where my work has been in this is to see it from start to finish the campaign fully come to life, working with Hoka directly, working with REI directly to really day-to-day understand what are the marketing campaign components, how is this going to come to life across social media, NPR on each of our websites, all three brands, websites, how is this coming to life? What kind of partners are we bringing in to help tell this story as well? So we're working with Patagonia as an influencer ambassador of this project, which is really exciting. And then really just seeing it through to the finish line now of launching the campaign. And then we're launching an event component with all of it as well. Cotopaxi is known for a Quest event. Have you heard of it before?\n\nCole Heilborn (12:53): No. Say that again.\n\nCarie Behe (12:54): Quest is what it's called.\n\nCole Heilborn (12:56): No, I'm unfamiliar.", "token_estimate": 512, "speakers": ["Carie Behe", "Cole Heilborn"], "start_timestamp": "10:51", "end_timestamp": "12:56", "podcast_index": 62, "episode_name": "EP 63: Carie Behe | Inclusivity and Marketing | Cotopaxi", "slug": "ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "web_url": "https://www.portsidepro.com/podcast-feed/ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "guest_name": "Carie Behe", "guest_title": "GTM Marketing Manager, Cotopaxi", "categories": [], "short_description": "How can brands speak to people who might not feel included?", "podcast_length": "44:85"}, {"id": "1e642ab6-a171-4c67-bf04-8147829ef132", "episode_id": "3e7889c2-9d6c-435a-a418-c44adcef7ff3", "cms_item_id": "68225dfc7bb476527f8c4869", "chunk_index": 7, "content": "Carie Behe (12:57): Adventure Race. Adventure Scavenger Hunt. Essentially, it was a big component of how the brand was launched in reaching a younger audience was creating this massive in-person event where thousands of participants are coming together and they're forming teams and they're being given a list of challenges to complete. And there's different challenge categories and some challenges are worth more points than others. And then you have to essentially take a picture of it, share it on social media in the early years of when these events were happening. So that's how a lot of user generated content was created. How Cotopaxi started getting out there through word of mouth, through social media, was participants of these questionable events were sharing each of their challenges through social (13:42): And with this. So the event has evolved I think over the years and specifically last year, the event, it was called Quest Quarantine, so it was a quarantine focus 72 hour, it was in April. So it was right when lockdowns were really starting to happen in a big way where Cotopaxi created this challenge list for you and to complete with your family in and around your home. And it was super successful. They almost 4,000 people signed up to participate in it. And then this year we decided this would be a fun component with Hoka to encourage people in a COVID responsible way. We know we're still in the middle of a pandemic, but more people are getting comfortable getting outside, but that you are finding a few friends that you potentially in your quarantine bubble that you can go and do these challenges within your community. (14:35): And so that will be a part of the collaboration as well. So very, from a marketing perspective, it's a very holistic campaign. You have everything rolling out on a website, it's coming to life in REI retail stores. You have a social media component where you have and influencers talking about it, and then you have an event component as well to give the audience a real chance to participate in it. And then I would say at the heart of this entire collaboration is a give back component because that is the root of who our brand is. And Hoka as well, it's very important to Hoka of giving back and we selected Big City Mountaineers as a nonprofit organization to partner with on this whole collaboration. And so there will be a grant donated to Big City Mountaineers after all of this. So a portion of all sales of each pair of shoes in each pack and ticket sales from Quest will go to big city Mountaineers, which is really", "token_estimate": 647, "speakers": ["Carie Behe"], "start_timestamp": "12:57", "end_timestamp": "12:57", "podcast_index": 62, "episode_name": "EP 63: Carie Behe | Inclusivity and Marketing | Cotopaxi", "slug": "ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "web_url": "https://www.portsidepro.com/podcast-feed/ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "guest_name": "Carie Behe", "guest_title": "GTM Marketing Manager, Cotopaxi", "categories": [], "short_description": "How can brands speak to people who might not feel included?", "podcast_length": "44:85"}, {"id": "826fef3c-fab3-4247-9cd5-91fb9478ff19", "episode_id": "3e7889c2-9d6c-435a-a418-c44adcef7ff3", "cms_item_id": "68225dfc7bb476527f8c4869", "chunk_index": 8, "content": "Cole Heilborn (15:32): Exciting. That's awesome. I got to imagine for you, you mentioned you've been doing this for about, well, you've been in the industry for about 12 years now, and I want to segue a little bit to your background and how you got into this space. Does it just feel weird and crazy that this is where you're at now because 12 years or so ago you were like, and I think what's really interesting about your story and what we'll get into is a lot of people are on this show and we talk about some of their career paths and everyone's path is a little different. It all winds changes and has its own roadblocks and variables, but I feel like a lot of people started out with some interest and some passion for being outdoors. And your story's a little different, which I think is really unique and I'm hoping you can kind of take us back to how you got started in the industry and I think your story's going to inspire and hopefully shed light on just career paths in general and breaking down some of the stereotypes around how do you get into the outdoor industry.", "token_estimate": 271, "speakers": ["Cole Heilborn"], "start_timestamp": "15:32", "end_timestamp": "15:32", "podcast_index": 62, "episode_name": "EP 63: Carie Behe | Inclusivity and Marketing | Cotopaxi", "slug": "ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "web_url": "https://www.portsidepro.com/podcast-feed/ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "guest_name": "Carie Behe", "guest_title": "GTM Marketing Manager, Cotopaxi", "categories": [], "short_description": "How can brands speak to people who might not feel included?", "podcast_length": "44:85"}, {"id": "40a2b3fe-5d55-469a-b4ad-3e8f37c6d71f", "episode_id": "3e7889c2-9d6c-435a-a418-c44adcef7ff3", "cms_item_id": "68225dfc7bb476527f8c4869", "chunk_index": 9, "content": "Carie Behe (16:32): Yeah, the story is, I kind of laugh at it now, like you said, it's a different path. I didn't grow up in an outdoorsy family, grew up with a dad who likes to go hunting and fishing and set up his tree stand at five in the morning in the middle of the woods in central Pennsylvania. And I wanted nothing to do with that. And the dead of winter, the thought of going out and doing that just wasn't registering with me for some reason. And my mom and her side of the family was just so traditional sports, football, basketball, and that's what I grew up doing. I always joke that my mom was not a fun person to be around on Sundays when the Steelers were losing. So I grew up near Pittsburgh and that was kind of my childhood, that outdoors was not a thing. (17:18): I did not go hiking. I camped once on an air mattress in a tent for a weekend I think in fifth grade. And then I got a crash course hard into the outdoors when I went to college. So I had somehow inadvertently signed up for this outdoor orientation program at West Virginia University. That was where I did my undergraduate. And I was literally there for student check-in day. And there was this table in the student union building with this guy, his name's Greg Corrio, and he was this program called Adventure West Virginia. And I walked by the table and he basically said, you get three credits to come camp for a week in the summer in West Virginia before you become a freshman, you should do it. And I just thought, oh yeah, cool. This sounds fun. So I just signed up completely, just no idea what I was signing up for, wrote the check, walked on. (18:10): And then in August, so about three weeks before my freshman year started, I went on this trip and I vividly remember some of my guy friends making fun of me a week before the trip. I was like, do you think I can bring a hair dryer on this? And they were like, you are going to fail miserably at all of this. They knew what I was signing up for and I didn't. So we get there and literally spent a week around the wilderness of West Virginia. We did a whole road trip loop, we went rock climbing in Cooper's Rock. We learned how to roll kayak in the pool at the rec center the first night. We would sit around the campfire every single night and literally have class. So we would talk about, okay, we went rock climbing today. Did you make it to the top? (18:54): How can you relate that to college experience? We went backpacking to the highest point in the state of West Virginia, Bruce Knob, and I'm not even exaggerating, I didn't know what the word backpacking meant until I had 50 pounds strapped in my back and I was dead last in that. I was just huffing and puffing along, almost crying thinking, what did you sign yourself up for? This is wild. But again, I didn't make it to the top of the rock wall. We went whitewater rafting and I think I cried on that. I was so just completely shocked, had never done anything like this in my life. And I made it to the top of the backpacking trip and was just so overcome with a sense of empowerment. Just I did that. Was I the fastest? Absolutely not. I was dead last an hour behind everybody probably they were radioing, where is she? (19:44): But I made it and it taught me so much and I just started to fall in love with the outdoors. Went on a spring break backpacking trip to Utah that same year, studied abroad New Zealand after that. And then I became a leader for that program three summers later. So I then got to be that leader and teacher for these incoming freshmen and the girls that were coming in specifically where they may have been so out of their element that I could relate to them and help let them know that it was okay and that everybody starts somewhere in the outdoors. But that was my crash course into outdoor rec. And I think once you fall in love with it, you start to get into gear culture and you see, I saw my leaders with Chacos and Nalgene bottles stickered up and I'm like, I want to be like them and look like them. (20:32): And that's how I discovered Keen and Keen. So Keen at the time, this is like 2007, they are doing this big sustainability campaign. And at the time, so Linda Balfour, I believe she was on your show earlier, she was one of the point people this campaign, and she became my boss eventually. But they were doing this tour around the entire US 50 different colleges. They were doing a documentary showing and essentially this environmental campaign and they had a brand ambassador at each college. And I became the brand ambassador through a phone call and two free pairs of shoes was my compensation. And they mailed me this event kit and they said, okay, you have to put an event on and promote it so people can come.", "token_estimate": 1193, "speakers": ["Carie Behe"], "start_timestamp": "16:32", "end_timestamp": "16:32", "podcast_index": 62, "episode_name": "EP 63: Carie Behe | Inclusivity and Marketing | Cotopaxi", "slug": "ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "web_url": "https://www.portsidepro.com/podcast-feed/ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "guest_name": "Carie Behe", "guest_title": "GTM Marketing Manager, Cotopaxi", "categories": [], "short_description": "How can brands speak to people who might not feel included?", "podcast_length": "44:85"}, {"id": "36453fee-c7f5-4d6e-9aca-7fc7e799828b", "episode_id": "3e7889c2-9d6c-435a-a418-c44adcef7ff3", "cms_item_id": "68225dfc7bb476527f8c4869", "chunk_index": 10, "content": "Cole Heilborn (21:16): And why'd you sign up for this? Was this something you were studying that was related to your field of study or did it just sound fun?\n\nCarie Behe (21:23): It was related to my field of study. So I was studying marketing and I had kind of given up hope of finding an internship that was start of my junior year and I was just not seeing any real true marketing internships. I was seeing sales types of opportunities and finance, but no marketing internships.\n\nCole Heilborn (21:41): I\n\nCarie Behe (21:41): Was by a stroke of luck that I happened to look at my email that day and it said, keen is seeking brand ambassador. And my thoughts literally were, I don't think anyone knows who Keen is unless you're an outdoorsy person. I think they only had two people apply. So I got the phone call, I got my two free pairs of shoes and had to put on an event.\n\nCole Heilborn (22:01): And that was your first taste? That was\n\nCarie Behe (22:04): First taste in real gorilla style marketing too. I started promoting all over campus. I had partnered with my boss, Greg for of that adventure program and I asked him if we could offer extra credit to all the participants if they came to the event. So that was a huge traffic driver. I remember sidewalk chalking like the university sidewalks the night before and someone came up and asked what I was doing. It was just a lot of just gorilla style marketing tactics on the ground, like giving people postcards in the student union building, going and talking to organizations on campus. And Keenan ultimately said, whoever they incentivized it, they said, whoever gives the best presentation has the most successful presentation, we'll give you a summer internship with us. So that's what I saw and I was like, I have to get this. And never in my wildest dreams did I think I would and I did.\n\nCole Heilborn (22:58): Wow. So you're out there the night before, chalking up the pavement trying to get people to show up to this event and then it goes really well?", "token_estimate": 506, "speakers": ["Cole Heilborn", "Carie Behe"], "start_timestamp": "21:16", "end_timestamp": "22:58", "podcast_index": 62, "episode_name": "EP 63: Carie Behe | Inclusivity and Marketing | Cotopaxi", "slug": "ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "web_url": "https://www.portsidepro.com/podcast-feed/ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "guest_name": "Carie Behe", "guest_title": "GTM Marketing Manager, Cotopaxi", "categories": [], "short_description": "How can brands speak to people who might not feel included?", "podcast_length": "44:85"}, {"id": "857fbec7-d95b-4b5f-b262-baf375657e14", "episode_id": "3e7889c2-9d6c-435a-a418-c44adcef7ff3", "cms_item_id": "68225dfc7bb476527f8c4869", "chunk_index": 11, "content": "Carie Behe (23:06): Yeah, it went super well. I had marketed it with show up to the event with a recycled item and you could get extra raffle tickets for prizes. So I'd gone to one of Keen's local retailers at the time in Morgantown. It was a store called Adventures Edge, and I asked them if they could donate prizes. They did Keen donated prizes, and I was really floored at the quantity of recycling items people were bringing. I remember taking Linda to the recycling center at the end of the event and we're just tossing all this recycling into bins and it was really cool.\n\nCole Heilborn (23:40): Wow. So then from there, where did you go after that?\n\nCarie Behe (23:45): Got the internship and I moved to Portland and that was my first time really being on the West Coast and experiencing the northwest and got this three month internship with them to really see that whole campaign through, it was a big event at the end of the summer that culminated the whole campaign. It was called Stand. I got to recruit and have some grassroots marketing volunteers help me just promote the event. And then when I left, I had a semester left to finish at WVU, but when I left they had said, if there's a full-time position when you graduate, it's yours if you want. And thankfully, about nine months later they did. So 2009 I moved to Portland permanently and started working for Keen and was there for about seven years.\n\nCole Heilborn (24:30): Wow. And what was your role there?\n\nCarie Behe (24:34): I was a marketing coordinator to start and just got to help support on a wide variety of marketing, different events, trade shows, was really helping with outdoor retailer and Keen's presence there and all the shoe sales that Keen would do. And then started to graduate more into public relations and having responsibility of managing the agency, developing PR strategy with 'em and then working with our product line managers to help bring all the product stories to life through PR and then some of the campaigns.\n\nCole Heilborn (25:06): Okay, gotcha. So that brought you up to year seven and then from seven to now can you fill where's, where's that time at?", "token_estimate": 540, "speakers": ["Carie Behe", "Cole Heilborn"], "start_timestamp": "23:06", "end_timestamp": "25:06", "podcast_index": 62, "episode_name": "EP 63: Carie Behe | Inclusivity and Marketing | Cotopaxi", "slug": "ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "web_url": "https://www.portsidepro.com/podcast-feed/ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "guest_name": "Carie Behe", "guest_title": "GTM Marketing Manager, Cotopaxi", "categories": [], "short_description": "How can brands speak to people who might not feel included?", "podcast_length": "44:85"}, {"id": "fbb99906-119e-43dd-b01a-e3933e01f3a8", "episode_id": "3e7889c2-9d6c-435a-a418-c44adcef7ff3", "cms_item_id": "68225dfc7bb476527f8c4869", "chunk_index": 12, "content": "Carie Behe (25:15): I spent time as a marketing manager at Danner Boots and got a taste of the hunt fish side of the outdoor industry. It was working.\n\nCole Heilborn (25:24): Bringing it back to your dad.\n\nCarie Behe (25:25): Yeah, he was so excited. Oh my God. He was just so yeah, right up his alley. And then after that I went to Leatherman. So again, continuing with everybody was looking forward to getting Leatherman's and I got to learn a lot at Leatherman actually. I really got to take management and ownership of campaign development and really help building that from the ground up because Leatherman historically wasn't really building these big rich marketing campaigns. It was more like, here's a tool, it does X, Y, and Z for you. And then when I came on board it was really, we were working under a new VP of marketing, Bobby Parisi at the time, and she's been in the industry forever and is a wonderful person mentor of mine, learned so much from her and she really was trying to get leatherman to story tell and build that emotional connection to the consumer. (26:18): And I think today if a brand is not doing that, it's not going to be successful in resonating with the millennial generation and down. It's just like you have to tell these really rich stories to build that bridge between the consumer to relate to them because that's what they're seeking. And so we got to do that with leatherman and tell real life consumer stories of how a leatherman saved the day for somebody or even saved their life. And it was a very humbling experience to get to put those types of stories into marketing campaigns. And then I ultimately got to work on some international marketing before I left and really helped just building a consistent look and feel for the brand globally. And that was something that the brand didn't really have before that it's very widely distributed across the world, over 50 countries, but every country was sort of doing their own thing to a degree they were given assets, but there wasn't this global campaign and strategy that came from HQ and out to all the other countries. So I was really trying to spearhead that effort of getting everyone aligned on the same page, having a consistent look and feel and tone of brand voice across all different regions of the world.", "token_estimate": 579, "speakers": ["Carie Behe", "Cole Heilborn"], "start_timestamp": "25:15", "end_timestamp": "25:25", "podcast_index": 62, "episode_name": "EP 63: Carie Behe | Inclusivity and Marketing | Cotopaxi", "slug": "ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "web_url": "https://www.portsidepro.com/podcast-feed/ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "guest_name": "Carie Behe", "guest_title": "GTM Marketing Manager, Cotopaxi", "categories": [], "short_description": "How can brands speak to people who might not feel included?", "podcast_length": "44:85"}, {"id": "be07e1f1-ccae-4a36-8a1b-cc0892044713", "episode_id": "3e7889c2-9d6c-435a-a418-c44adcef7ff3", "cms_item_id": "68225dfc7bb476527f8c4869", "chunk_index": 13, "content": "Cole Heilborn (27:34): Gotcha. So I'm curious through all of that, through I guess your perspective of the outdoors and your relationship with the outdoors as it's evolved. How has that affected your perspective with the outdoor industry, with the marketing industry and the work that you do now?\n\nCarie Behe (27:53): I would say it, it's greatly impacted how I look at I how approach my day to day, but just how the outdoor industry approaches building connections with consumers and the spectrum of the outdoor consumer is so vast. It's like you've got the very hardcore outdoor, the person that's going and doing laps up a mountain and then the person that has never even doesn't even know what a hike is or doesn't know what the word backpacking means. There's such a range there and each of those types of personas exist. So how does the outdoor industry, how does the epoxy a key and a leatherman, how do these brands really start identifying how they can talk to people that might not feel like they belong? And I think my personal experience, it resonates so much with that because I didn't feel like I belonged, especially on that trip. (28:46): And even sometimes to this day is like I'm not the fastest in what I do. I've experienced with, I think with the gear culture of the outdoor industry, you have to have the lightest, the fastest, the next greatest thing. Oftentimes a lot of garments haven't fit me. There's been jackets that it's like I can't fit into it. And then you start to doubt yourself of really, do I fit in? Is this, am I meant to be going and doing this? Do I have to have that jacket to then take me up to the mountain? What if it doesn't fit? There's this doubt that gets put in your head. I mean you put it in your head, but when you don't see yourself represented in marketing collateral, in messaging from outdoor brands, it might be a bit alienating. And I mean I think generally inclusivity is a topic the industry is talking about, but inclusivity across the board with your skin color, with how you identify with your body size and type of just, these are conversations I think that we need to have together and rally around. (29:50): It is a common thing that I think if all brands are rallying together, we're going to identify a solution to make everyone feel welcome. And I think I said this to you before, the trees don't care what you look like. They don't care how much you weigh or not what your skin color is. I mean the outdoors are for every single person. And I think at times where I felt like I don't belong, I mean for sure, am I in my head? Absolutely. But when I don't see myself represented at times it might help just subliminally amplify that. And how can we as brands make people feel comfortable in general of like, do you need that jacket to go out and hike a few miles away? Maybe not, but do you need the jacket to go scale Mount Hood or Mount Rainier maybe.", "token_estimate": 731, "speakers": ["Cole Heilborn", "Carie Behe"], "start_timestamp": "27:34", "end_timestamp": "27:53", "podcast_index": 62, "episode_name": "EP 63: Carie Behe | Inclusivity and Marketing | Cotopaxi", "slug": "ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "web_url": "https://www.portsidepro.com/podcast-feed/ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "guest_name": "Carie Behe", "guest_title": "GTM Marketing Manager, Cotopaxi", "categories": [], "short_description": "How can brands speak to people who might not feel included?", "podcast_length": "44:85"}, {"id": "d37275b7-aec3-45c1-84d9-b708ff416780", "episode_id": "3e7889c2-9d6c-435a-a418-c44adcef7ff3", "cms_item_id": "68225dfc7bb476527f8c4869", "chunk_index": 14, "content": "Cole Heilborn (30:39): Interesting. I'm curious. I feel like kind of what you're describing is imposter syndrome, feeling like you don't belong\n\nCarie Behe (30:45): A little bit,\n\nCole Heilborn (30:46): But I would assume anyone or myself looks at you and you're like, Carrie is doing an awesome job, she's in the industry, she's been doing it for a long time. But that still plagues you sometimes that doubt.\n\nCarie Behe (31:01): I think so. I think especially when it comes to buying a garment and it might not fit. I have that moment of doubt. I mean that's for sure on me, but it's really cool to see brands starting to address their marketing collateral to make it more representative of anyone and everyone. That's the first very obvious and easy step. I think all brands should be getting behind at this point. And there's so many leaders in the industry that have been doing it for years already, but how do you keep, what's the next step in that? I mean it's inclusivity with sizes and building a more comprehensive range of sizes for people of all body sizes and shapes to fit into.\n\nCole Heilborn (31:45): I am curious, I think regardless of, I guess what people feel like feel an imposter about, I feel like imposter syndrome is a pretty common thing that a lot of people feel. Speaking personally, that's something that I experience more frequently than not. It seems like just around lots of different things, work related, not work related. I'm curious because I think a lot of people who are listening are probably going to resonate and connect with you on this level. What do you do in those moments of doubt? What truth do you recall? Do you anchor yourself in so that you can get through those hazy moments?", "token_estimate": 432, "speakers": ["Cole Heilborn", "Carie Behe"], "start_timestamp": "30:39", "end_timestamp": "31:45", "podcast_index": 62, "episode_name": "EP 63: Carie Behe | Inclusivity and Marketing | Cotopaxi", "slug": "ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "web_url": "https://www.portsidepro.com/podcast-feed/ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "guest_name": "Carie Behe", "guest_title": "GTM Marketing Manager, Cotopaxi", "categories": [], "short_description": "How can brands speak to people who might not feel included?", "podcast_length": "44:85"}, {"id": "1c094be4-a566-4084-a184-081aa551820e", "episode_id": "3e7889c2-9d6c-435a-a418-c44adcef7ff3", "cms_item_id": "68225dfc7bb476527f8c4869", "chunk_index": 15, "content": "Carie Behe (32:27): I like this question. I'm glad that you're bringing this up. And I think the first step for me has just been a mental check with myself personally is just like, okay, why are you feeling this way? What's causing this? Is your work plate? Is there a lot on the work plate? Did you not hike that hike in a fast way? Were you super behind all your friends? I start to unpack why I'm feeling that way, but I think where it has been most beneficial, where I've started to feel less imposter syndrome is just talking to people about it and realizing that almost everyone I've ever talked to feels this way within their work and professional or even on personal things of just the doubting yourself. But if you talk through it and talk through it with a partner, a friend, a close coworker, just you'll find that they might be feeling similarly and that you can talk through it together. (33:24): And then I'd say on the professional side of things, just always having transparent conversations and wanting to learn where you stand in relation to your work plate and your responsibilities. If you're delivering on something and you're not getting clear feedback to help you progress and checking the box, then asking for it and being very blunt of just like, is this what you're looking for? And if not, can you help me understand why? I think a lot of the earlier years of my career feedback was given, I think from top down the executive level at companies, but there wasn't a lot of concrete explanation of I don't like this and here's why. It was just like, go fix this or go make it look different. And that wasn't, I think that helped continue to build this doubt of like, oh, I didn't do it right the first time, but I'm unclear of how to do it right the second time. And that really just comes from building the confidence to have those maybe difficult conversations with a manager or some other level. I always say powers that be is how I refer to executives is going to the powers that be. And just having that frank discussion of, you weren't looking for this, so just help me understand what you are looking for so I can come up with a solution", "token_estimate": 543, "speakers": ["Carie Behe"], "start_timestamp": "32:27", "end_timestamp": "32:27", "podcast_index": 62, "episode_name": "EP 63: Carie Behe | Inclusivity and Marketing | Cotopaxi", "slug": "ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "web_url": "https://www.portsidepro.com/podcast-feed/ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "guest_name": "Carie Behe", "guest_title": "GTM Marketing Manager, Cotopaxi", "categories": [], "short_description": "How can brands speak to people who might not feel included?", "podcast_length": "44:85"}, {"id": "dcd5c235-55ab-4dfa-a8a2-4adab6abdf66", "episode_id": "3e7889c2-9d6c-435a-a418-c44adcef7ff3", "cms_item_id": "68225dfc7bb476527f8c4869", "chunk_index": 16, "content": "Cole Heilborn (34:46): And feeling that way. I mean, it greatly affects how you're able to do your job. If we're just looking at it from the career perspective, then you start to second guess everything that you're doing and you're like, is this even a good idea because I'm maybe not the right person for this. Is this a good idea? And then it just spirals out of control.\n\nCarie Behe (35:07): Yeah, I would agree with that. And I think there comes a point for me, I mean I'm speaking from my own perspective and experience in the industry is like my competence has been built over time. I mean, I feel like I was terrified my first five years on the job of just like, am I doing this right? Am I not doing this right? And if a mistake happened, oh, I remember this very vividly. This was the first photo shoot I'd ever had a bigger responsibility and was with Keen. And we were going to Smith Rock to do a photo shoot and VP of marketing was coming along at the time and she allowed me to come along on the shoot and that was my first work trip. And I, I was responsible for all the samples and making sure we had everything for the shoot. And there was one pair of winter boots where I should have brought both colors and there was only one color, and my head is melting on the inside. I'm like, I'm going to lose my job. This is awful. She hates me. I just spiraled in my head like, well, we can't get the boots. So the reality is what it is, and obviously you learn in those moments. So I think that's a great example of, okay, I failed to bring the second color of boots, but the next time I brought them,\n\nCole Heilborn (36:19): Yeah, that gut drop feeling, when you realize that you just messed something up, it's painful", "token_estimate": 433, "speakers": ["Cole Heilborn", "Carie Behe"], "start_timestamp": "34:46", "end_timestamp": "36:19", "podcast_index": 62, "episode_name": "EP 63: Carie Behe | Inclusivity and Marketing | Cotopaxi", "slug": "ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "web_url": "https://www.portsidepro.com/podcast-feed/ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "guest_name": "Carie Behe", "guest_title": "GTM Marketing Manager, Cotopaxi", "categories": [], "short_description": "How can brands speak to people who might not feel included?", "podcast_length": "44:85"}, {"id": "b03dbfc5-09b8-425a-bd83-daa3f01752a5", "episode_id": "3e7889c2-9d6c-435a-a418-c44adcef7ff3", "cms_item_id": "68225dfc7bb476527f8c4869", "chunk_index": 17, "content": "Carie Behe (36:26): And it doesn't go away. It's like even with all the years of experience I've had now, there's still been moments because as you progress, your project plate gets bigger and all the balls are up in the air and you have to figure out how to juggle them. But that comes with having very clear, honest, transparent discussions with your manager. And I think when I was younger, I was afraid to say that I was afraid to say no, because if I said no, this is me in my head thinking this. If I said no, does that show them that I'm unwilling to be a good team member? Does that show that I don't want the responsibility? What does that me saying? No. So I never said no. And then a consequence of not saying no at times was dropping the ball on things. Something as simple as should have grabbed the pair of the second color. (37:15): And I didn't turned out to be a relatively big problem at the time, but you learn. But it comes with having those discussions with people of like, okay, if you have all this on your plate, help me prioritize. And so that's, I've learned to say no, but I say it in a way of I can get to that, but something else might not get worked on at the time. So understanding project management and it goes with go to market too of how to prioritize because all these different campaigns are being worked on at the same\n\nCole Heilborn (37:46): Time. Sure. So yeah. With your role now, I guess, what is Cotopaxi doing to create more of an inclusive environment or what have they done? What are you hoping to do in the future?", "token_estimate": 391, "speakers": ["Carie Behe", "Cole Heilborn"], "start_timestamp": "36:26", "end_timestamp": "37:46", "podcast_index": 62, "episode_name": "EP 63: Carie Behe | Inclusivity and Marketing | Cotopaxi", "slug": "ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "web_url": "https://www.portsidepro.com/podcast-feed/ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "guest_name": "Carie Behe", "guest_title": "GTM Marketing Manager, Cotopaxi", "categories": [], "short_description": "How can brands speak to people who might not feel included?", "podcast_length": "44:85"}, {"id": "2182df1a-9baf-45c0-a751-baf6bf73dca9", "episode_id": "3e7889c2-9d6c-435a-a418-c44adcef7ff3", "cms_item_id": "68225dfc7bb476527f8c4869", "chunk_index": 18, "content": "Carie Behe (38:00): I think that Cotopaxi is a brand has done so many awesome things right from the start. It is a brand that really is inclusive, I think across the board when it comes to messaging. I mean from a marketing perspective and building campaigns and showing representation of people of color, people of different body sizes. I think where I hope to see Cotopaxi go in the future, and I said this in my interviews and have talked with our product team about this, is the brand will have to at some point work on developing extended sizing. The size range that we offer in our products is the normal size range that you expect, but to offer additional sizes for different body types, that's my hope for it. And I know the product team feels that way. We've had many conversations about it and they're all really positive, great conversations. I think as the brand grows in terms and scales, we'll be able to do that.\n\nCole Heilborn (38:59): How do you consider inclusivity? What does that look like in the things that you're working on today? Has that influenced how you're working on this collaboration project?", "token_estimate": 281, "speakers": ["Carie Behe", "Cole Heilborn"], "start_timestamp": "38:00", "end_timestamp": "38:59", "podcast_index": 62, "episode_name": "EP 63: Carie Behe | Inclusivity and Marketing | Cotopaxi", "slug": "ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "web_url": "https://www.portsidepro.com/podcast-feed/ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "guest_name": "Carie Behe", "guest_title": "GTM Marketing Manager, Cotopaxi", "categories": [], "short_description": "How can brands speak to people who might not feel included?", "podcast_length": "44:85"}, {"id": "53d1b02e-f944-4cab-8851-9fc5caf3d58d", "episode_id": "3e7889c2-9d6c-435a-a418-c44adcef7ff3", "cms_item_id": "68225dfc7bb476527f8c4869", "chunk_index": 19, "content": "Carie Behe (39:10): Yeah, I would say it's influenced the collaboration project in terms of the way we're developing the messaging for it really of the message of the product itself can be used for a wide range of things. One of the things that I think obviously that comes to mind with Hoka is a brand is running. I personally not a runner myself, it's a brand I haven't identified with personally and have known of it. But I think where you get into the marketing messaging and storytelling is being able to explain, these shoes can take you on a run, on a trail hike, on a walk around your neighborhood. And the same on the Cotopaxi side with the pack. The pack could be a trail running pack. The pack could be for a day hike, it could be your commuter pack, but that these two brands are getting together and building a message of multiple different benefits that the product could serve the consumer. And then just making sure from the campaign, the look and the feel of it that people are represented in it, that people of color are represented. I would say from a lifestyle perspective with capturing imagery for the campaign and making sure that there is representation, that there's representation even in the activity itself of making sure that the images, that what you see being portrayed in the image makes sense across a wide variety of activities.\n\nCole Heilborn (40:37): You brought up something interesting that I'd be curious to hear your response to you as a marketer. You don't personally connect with the brands like Coca, but talking about imposter syndrome, does that bring about concerns about your qualifications to work on a project like this?", "token_estimate": 418, "speakers": ["Carie Behe", "Cole Heilborn"], "start_timestamp": "39:10", "end_timestamp": "40:37", "podcast_index": 62, "episode_name": "EP 63: Carie Behe | Inclusivity and Marketing | Cotopaxi", "slug": "ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "web_url": "https://www.portsidepro.com/podcast-feed/ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "guest_name": "Carie Behe", "guest_title": "GTM Marketing Manager, Cotopaxi", "categories": [], "short_description": "How can brands speak to people who might not feel included?", "podcast_length": "44:85"}, {"id": "e473dc5f-7a61-4fa2-97ef-0d8c0bcdd8e3", "episode_id": "3e7889c2-9d6c-435a-a418-c44adcef7ff3", "cms_item_id": "68225dfc7bb476527f8c4869", "chunk_index": 20, "content": "Carie Behe (40:57): God, I love that. That's such a great question. I guess maybe initially it brought up concerns. I think when I first started working with the Hoka team, I was nervous. I'm not a runner. I mean, I don't think I could even run half a mile right now, not my thing. There's other ways I get outside or other ways I'm active. Cycling or snowboarding is a thing. But even one of the first meetings, I pronounced the brand name wrong, how disconnected I think I am personally from the brand, I was so embarrassed I didn't say Hoka. And they were wonderful though. The team was like, it's not Hoka one, one, Carrie. So I think in the initial stages of it, I did feel like a huge imposter of like, oh my God, I have to represent my brand and beyond my game for my brand that I'm brand new to. (41:51): And then I have to help be a steward of another brand that's a really incredible, awesome brand. And when I can't even pronounce the name, what does that show? But I think we've grown a lot since then and it's been so wonderful. I've been working with Leah Lodge at Hoka. She has just been phenomenal, such a great partner to, we're just in such lockstep on this whole campaign and seeing it through from no ideas of how we're going to, what's the campaign messaging, how are we going to tell this story to then bringing our creative teams together to start making the building blocks of that, bringing in partners like Patty, bringing in other ambassadors and influencers, working with an REI and help tell that story through the REI lens as well. It's been really cool. So I would say the imposter syndrome is definitely gone. But yeah, I had some fun fail moments in the beginning, but like I said before, you learn, I now learn how to correctly pronounce their name.", "token_estimate": 446, "speakers": ["Carie Behe"], "start_timestamp": "40:57", "end_timestamp": "40:57", "podcast_index": 62, "episode_name": "EP 63: Carie Behe | Inclusivity and Marketing | Cotopaxi", "slug": "ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "web_url": "https://www.portsidepro.com/podcast-feed/ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "guest_name": "Carie Behe", "guest_title": "GTM Marketing Manager, Cotopaxi", "categories": [], "short_description": "How can brands speak to people who might not feel included?", "podcast_length": "44:85"}, {"id": "efec4071-c31b-4b34-8136-c7fa495d2081", "episode_id": "3e7889c2-9d6c-435a-a418-c44adcef7ff3", "cms_item_id": "68225dfc7bb476527f8c4869", "chunk_index": 21, "content": "Cole Heilborn (42:55): But I am curious if you can dive a little deeper. I feel like that's, especially in the outdoor industry, I hear this everywhere. You get a job at a company that you personally are passionate about and that you practice outside of work hours because most people who are in the space live their passion and their passion is their work. But that's always, I mean obviously that's not practical for everyone and for every job in the industry. But I guess, do you feel like there's an edge or a value to either being outside of using this runner example, being outside of that industry looking in? Do you feel like there's added value being on the inside, looking out as you're in those positions? Is one better than the other? Is that a thing?\n\nCarie Behe (43:51): I think they're both equally important. I think the fact that I'm this outside non runner looking into a brand like Hoka is hopefully offering that perspective from an inclusive message type of point of view of like, Hey, if this is so run focused, are we alienating somebody that might not be a runner? So I would say from the outside looking in, I think it offers huge opportunity to just, I mean, and this is true for any brand of internally, you are the experts of your brand, it best and the truth as you see it, but somebody on the outside might see it entirely differently. And so I think being willing to be open to hearing that perspective, it's so, so valuable because I think it helps shape and create something that resonates with somebody on the outside. So I would even say that might be the more important of the two, but I think being that expert on the inside of knowing it and you're eating, sleeping, breathing, if you are working for a running brand, a snowboarding brand, a climbing brand, that having that level of expert knowledge of the sport that your gear is going to support, I think is super critical as well. (45:03): So it's finding the right balance with it, of being the expert inside, but being willing to hear outside perspective too.", "token_estimate": 514, "speakers": ["Cole Heilborn", "Carie Behe"], "start_timestamp": "42:55", "end_timestamp": "43:51", "podcast_index": 62, "episode_name": "EP 63: Carie Behe | Inclusivity and Marketing | Cotopaxi", "slug": "ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "web_url": "https://www.portsidepro.com/podcast-feed/ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "guest_name": "Carie Behe", "guest_title": "GTM Marketing Manager, Cotopaxi", "categories": [], "short_description": "How can brands speak to people who might not feel included?", "podcast_length": "44:85"}, {"id": "60d40cad-860f-46b2-b7f6-ce8c84b4f590", "episode_id": "3e7889c2-9d6c-435a-a418-c44adcef7ff3", "cms_item_id": "68225dfc7bb476527f8c4869", "chunk_index": 22, "content": "Cole Heilborn (45:09): Sure. Yeah, no, that's a really nice way of putting it. So we're almost out of time for today, but one of my last questions, I'm just curious, what's your hope as you look forward towards the future, both for you personally, for the industry as a whole? Any thoughts?\n\nCarie Behe (45:28): Yeah. I would say hopes and dreams for, I think personally is I want to find a way I feel like I can be accomplished in my job and in my career. And if I've left a mark at all in the outdoor industry is I want someone who felt like they were excluded to feel included. I want the industry to just have this outdoors for all mentality. It doesn't matter the activity, it doesn't matter what you're wearing at the end of the day if you're getting outside. I learned so much during that adventure, West Virginia. I mean, that program truly changed the course of my life. I would not be in the outdoor industry. We're probably talking to you right now, but I learned so much about me and what the outdoors gave to me is so invaluable. And it's like that inspired me to want to continue on my journey and helping protect the places that we play, helping just get more people out to enjoy and learn as I have. (46:26): And so if I can inspire someone who may otherwise not have gotten outside to go take a hike for the first time in their local park or to go on a bike ride is I feel like I've done my job. And how as the industry, we can take that mentality of inspiring, especially the next generation of outdoor enthusiasts, like younger kids that are growing up today that maybe grew up like me that didn't have an outdoor experience. How can we find ways to expose them? Because the power of the outdoors is like, it's so magical. It's hard to put into words. I'm sure you know that too. And you've felt that. And so how can the industry really rally together to create this next generation of stewards and this next generation of people who are passionate about getting outside and exploring. So that's why, but I hope happens.\n\nCole Heilborn (47:20): I love that. If folks want to follow along with you or with the brand, where can people go to say hello?", "token_estimate": 542, "speakers": ["Cole Heilborn", "Carie Behe"], "start_timestamp": "45:09", "end_timestamp": "47:20", "podcast_index": 62, "episode_name": "EP 63: Carie Behe | Inclusivity and Marketing | Cotopaxi", "slug": "ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "web_url": "https://www.portsidepro.com/podcast-feed/ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "guest_name": "Carie Behe", "guest_title": "GTM Marketing Manager, Cotopaxi", "categories": [], "short_description": "How can brands speak to people who might not feel included?", "podcast_length": "44:85"}, {"id": "7b3067af-5348-4326-b7f4-d7322ad28ada", "episode_id": "3e7889c2-9d6c-435a-a418-c44adcef7ff3", "cms_item_id": "68225dfc7bb476527f8c4869", "chunk_index": 23, "content": "Carie Behe (47:25): LinkedIn probably is the easiest way to find me. Just behe on LinkedIn. And I would say same with Co Epoxy. We're pretty active on our LinkedIn channel and our Instagram is just at epoxy. So follow along for some outdoor adventure and some llama cuteness.\n\nCole Heilborn (47:42): Sounds good. Well, Carrie, thank you again for taking the time and I hope you have a great rest of your day.\n\nCarie Behe (47:47): Thanks, you too.\n\nCole Heilborn (47:48): Alright, see you. Thank you for listening to this episode of the Backcountry Marketing Podcast. If you enjoyed today's episode or learned something new, please consider leaving us a review on Apple or sharing this with a friend.", "token_estimate": 175, "speakers": ["Carie Behe", "Cole Heilborn"], "start_timestamp": "47:25", "end_timestamp": "47:48", "podcast_index": 62, "episode_name": "EP 63: Carie Behe | Inclusivity and Marketing | Cotopaxi", "slug": "ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "web_url": "https://www.portsidepro.com/podcast-feed/ep-63-carie-behe-inclusivity-and-marketing-cotopaxi-186e4", "guest_name": "Carie Behe", "guest_title": "GTM Marketing Manager, Cotopaxi", "categories": [], "short_description": "How can brands speak to people who might not feel included?", "podcast_length": "44:85"}, {"id": "1d2eca02-a470-4305-9a0f-f5071b5dae21", "episode_id": "926ad7a4-d22c-4225-845c-b8845aa6439e", "cms_item_id": "68225dfc7bb476527f8c4868", "chunk_index": 0, "content": "Maddie Duffy (00:03): The biggest thing that I can say about any Ambassador program is just the relationship. Just really appreciate that relationship that you have with each of the ambassadors and nurture it. And I dunno, for me, I'm lucky because I can call all of our ambassadors, my friends. They're just such amazing people and it's always an honor to work with them and then an honor to see what they can produce for Mystery Ranch.\n\nCole Heilborn (00:30): Welcome to the Backcountry Marketing Podcast. My name is Cole Holborn and I'll be your host today. This podcast dives deep with leaders of the outdoor marketing industry as they discuss the gritty details of their work, personal challenges and latest adventures, whether you're standing in the lift line, shuttling to fresh loam, or cracking a local beer. I hope you enjoyed today's episode. This is the Backcountry Marketing Podcast. This episode is produced by Portside Productions, an outdoor, commercial and film production company based in the Pacific Northwest. Welcome to the Backcountry Marketing Podcast. My name is Cole Holborn. Today I'm sitting down with Maddie Duffy, the marketing manager at Mystery Ranch. Maddie, how are you?\n\nMaddie Duffy (01:11): I'm good. How are you doing?\n\nCole Heilborn (01:14): Doing wonderful. Thanks for joining us today. Where are you calling in from?\n\nMaddie Duffy (01:18): I am calling in from Bozeman, Montana.\n\nCole Heilborn (01:21): Okay, right on. So I'd love to hear more about Mystery Ranch. Maybe fill us in for folks who aren't super familiar with the company, I guess, what's your background? What do you guys specialize in? What do you do?\n\nMaddie Duffy (01:34): Yeah, so I have been at Mystery Ranch for just about three years working in the marketing department. And what Mystery Ranch is, is we're a backpack company and we make backpacks for the military for wild land firefighters, for back country hunting, for any recreational use, whether that's day hikes or long expedition hikes, and then also travel.", "token_estimate": 507, "speakers": ["Maddie Duffy", "Cole Heilborn"], "start_timestamp": "00:03", "end_timestamp": "01:34", "podcast_index": 64, "episode_name": "EP 64: Maddie Duffy | Ambassador, Athlete or Influencer? | Mystery Ranch", "slug": "ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "web_url": "https://www.portsidepro.com/podcast-feed/ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "guest_name": "Maddie Duffy", "guest_title": "Marketing Manager, Mystery Ranch", "categories": [], "short_description": "When it comes to building your team who are you working with? Why would you choose an athlete over an influencer? When is an influencer better suited than an ambassador? Why have an ambassador team in 2021?", "podcast_length": "44:86"}, {"id": "ec3c317b-386c-458b-aca0-35d823b6a076", "episode_id": "926ad7a4-d22c-4225-845c-b8845aa6439e", "cms_item_id": "68225dfc7bb476527f8c4868", "chunk_index": 1, "content": "Cole Heilborn (01:59): Okay. It's interesting, I think in the outdoor space we see a lot of backpack companies, but there's not a lot of backpack companies that I'm aware of that go outside of the traditional hike and climb. How many other brands are in the spaces that you operate in forest firefighting, in military, in the hunting space,\n\nMaddie Duffy (02:20): In the military, and in the fire, not as many. But in the hunting space, we've definitely seen an increase of different brands that also make hunting packs. But I think what makes us unique is that we're not only hunting packs, and I think that's kind of what you see throughout the different markets is each company only kind of their niche is hunting or fire or military, and it's not a combination of all of them.\n\nCole Heilborn (02:51): Sure. Yeah. So I guess kind of break that down. How did Mr. Man get started? How did you get into all of these different verticals?\n\nMaddie Duffy (02:59): Yeah, so actually Dana Gleason, who owns Mystery Ranch, he started Dana Design and gosh, I think that was early nineties. And then he sold it to K two and just kind of realized that his backpacking days were not done. And with Dana Design, he really focused on the outdoor side of things, so whether that be climbing or skiing or hiking. And then when he started Mystery Ranch, the outdoor market wasn't doing all that great. We were kind of struggling to keep afloat, and then we were approached by the military to start making military packs. And so the military is kind of what saved Mystery Ranch and kept Mystery Ranch up and running. And then eventually we had a wild land firefighter approached Dana about making backpacks, and that's when we started doing the wildland fire side of things. And then we started to expand into the hunting side of things as well.\n\nCole Heilborn (04:02): I'm really curious to learn a little bit more about your job as a marketing manager. I know one of the things that you work on and oversee is the ambassador program, but kind of fill us in on the rest of your, I guess, job duties.", "token_estimate": 521, "speakers": ["Cole Heilborn", "Maddie Duffy"], "start_timestamp": "01:59", "end_timestamp": "04:02", "podcast_index": 64, "episode_name": "EP 64: Maddie Duffy | Ambassador, Athlete or Influencer? | Mystery Ranch", "slug": "ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "web_url": "https://www.portsidepro.com/podcast-feed/ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "guest_name": "Maddie Duffy", "guest_title": "Marketing Manager, Mystery Ranch", "categories": [], "short_description": "When it comes to building your team who are you working with? Why would you choose an athlete over an influencer? When is an influencer better suited than an ambassador? Why have an ambassador team in 2021?", "podcast_length": "44:86"}, {"id": "6327eef3-7057-4181-a3cc-151ec37f32e7", "episode_id": "926ad7a4-d22c-4225-845c-b8845aa6439e", "cms_item_id": "68225dfc7bb476527f8c4868", "chunk_index": 2, "content": "Maddie Duffy (04:14): So I have been running mystery Ranch's social media for three years now. That's like our Instagram, our LinkedIn, our Twitter, and our Facebook. And then we're starting to expand a little bit more into YouTube and just kind of seeing what other platforms we're able to use. And then I also run our nonprofit program as well, which is made up, I believe, of 28 different nonprofits at this point that we're working with. And those nonprofits expand from the military side of things to land fired hunting, DEI, and then also outdoor.\n\nCole Heilborn (04:55): Okay, interesting. Yeah. Kind jumping back to that ambassador focus, I got to imagine that's pretty interesting for you. Since you guys work in so many different verticals, you're interacting with tons of different types of people from all of those different walks of life. What's that?\n\nMaddie Duffy (05:12): It's honestly incredible. I think it's one of, I mean, I love my job, but I think that's probably one of my favorite things about my job is just working with such a diverse crew of people. We have our hunting ambassadors, we have military ambassadors, we have brand ambassadors that kind of encompass more than just one market. We have ski ambassadors, climbing ambassadors, hunting everything. And just being able to have a relationship with each one of them has been probably the highlight of my job.\n\nCole Heilborn (05:50): Do you feel like you learn something unique from each of them? You wouldn't otherwise be able to learn if you didn't have the job?", "token_estimate": 387, "speakers": ["Maddie Duffy", "Cole Heilborn"], "start_timestamp": "04:14", "end_timestamp": "05:50", "podcast_index": 64, "episode_name": "EP 64: Maddie Duffy | Ambassador, Athlete or Influencer? | Mystery Ranch", "slug": "ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "web_url": "https://www.portsidepro.com/podcast-feed/ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "guest_name": "Maddie Duffy", "guest_title": "Marketing Manager, Mystery Ranch", "categories": [], "short_description": "When it comes to building your team who are you working with? Why would you choose an athlete over an influencer? When is an influencer better suited than an ambassador? Why have an ambassador team in 2021?", "podcast_length": "44:86"}, {"id": "a77ac3b5-1829-4a89-b2ed-a85baafe289d", "episode_id": "926ad7a4-d22c-4225-845c-b8845aa6439e", "cms_item_id": "68225dfc7bb476527f8c4868", "chunk_index": 3, "content": "Maddie Duffy (05:58): Oh, a hundred percent. I'm not a hunter by any means at all. The most hunting I've ever done is I accidentally ran over a raccoon and I cried for three hours. So I don't really know a whole lot about hunting. My brothers hunted a lot growing up, but it wasn't until I moved to Montana that I just learned more about it. And I think the most incredible thing about our ambassadors is they get really excited to talk about their hobby and talk about the things that they're really good at. And you can see all of that passion come from them, and then you get excited about it and you learn more about it. And so yeah, it is incredible working with people who have different hobbies that they excel in.\n\nCole Heilborn (06:45): Yeah. I'm curious to dive into this topic of ambassadors for today. There's no shortage of ambassadors, athletes, influencers in the outdoor space. I think we all have those ambassadors or individuals that we look up to on social and we're like, man, I just want to be like that person because look at that epic trip they just went on. From the brand side though, I'm curious to hear your perspective. How do you manage an ambassador program? How do you decide to start one, how do you find people to be on your ambassador program? And especially with social media today, there's influencers that are popping up and they're kind of changing the way that maybe brands look at ambassadors or athletes. And then there's a question of how do you quantify the results from the ambassadors? So I know that I just threw up a lot of different topics and I'm hoping we can whittle away at some of those today. So I guess first question, why have an ambassador program and what does mystery ranches look like?", "token_estimate": 437, "speakers": ["Maddie Duffy", "Cole Heilborn"], "start_timestamp": "05:58", "end_timestamp": "06:45", "podcast_index": 64, "episode_name": "EP 64: Maddie Duffy | Ambassador, Athlete or Influencer? | Mystery Ranch", "slug": "ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "web_url": "https://www.portsidepro.com/podcast-feed/ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "guest_name": "Maddie Duffy", "guest_title": "Marketing Manager, Mystery Ranch", "categories": [], "short_description": "When it comes to building your team who are you working with? Why would you choose an athlete over an influencer? When is an influencer better suited than an ambassador? Why have an ambassador team in 2021?", "podcast_length": "44:86"}]
